
const $=id=>document.getElementById(id),V=id=>+$(id).value;
const tabs=[['learn','Start here'],['circ','Circuits'],['dio','Diode'],['mos','MOSFET'],['bjt','BJT'],['rc','RC'],['op','Op-amps'],['lg','Logic'],['sv','Step by step'],['ex','Exercises'],['mk','Maker'],['pr','Practice'],['gm','Crack the Q 🎯'],['form','Formulas']];
const nav=$('nav');
tabs.forEach(([id,t],i)=>{const b=document.createElement('button');b.textContent=t;b.setAttribute('role','tab');b.onclick=()=>show(id);b.dataset.t=id;nav.appendChild(b)});
function show(id){tabs.forEach(([k])=>$(k).classList.toggle('on',k==id));[...nav.children].forEach(b=>b.setAttribute('aria-selected',b.dataset.t==id));draw();scrollTo(0,0)}
function sl(id,l,mn,mx,st,v,u){return `<div class="sl"><label for="${id}">${l}</label><b id="${id}o">${v} ${u}</b><input type="range" id="${id}" min="${mn}" max="${mx}" step="${st}" value="${v}" data-u="${u}"></div>`}
function sel(id,opts){return `<select id="${id}" aria-label="${id}">${opts.map(o=>`<option>${o}</option>`).join('')}</select>`}
document.addEventListener('input',e=>{const t=e.target,o=$(t.id+'o');if(o)o.textContent=t.value+' '+t.dataset.u;draw()});
const f=(x,d=2)=>(+x).toFixed(d).replace(/\.?0+$/,'');
const col=n=>({sig:'#2f7de1',out:'#e8590c'}[n])||getComputedStyle(document.documentElement).getPropertyValue('--'+n).trim();
function plot(cv,o){const r=devicePixelRatio||1,W=cv.width=cv.clientWidth*r,H=cv.height=cv.clientHeight*r,c=cv.getContext('2d');c.scale(r,r);const w=W/r,h=H/r,p=34;
const X=x=>p+(x-o.x0)/(o.x1-o.x0)*(w-p-8),Y=y=>h-p-(y-o.y0)/(o.y1-o.y0)*(h-p-10);c.clearRect(0,0,w,h);c.font='11px system-ui';c.fillStyle=col('mut');c.strokeStyle=col('line');
c.beginPath();c.moveTo(p,Y(0));c.lineTo(w-8,Y(0));c.moveTo(X(0),10);c.lineTo(X(0),h-p);c.stroke();c.fillText(o.xl,w-70,Y(0)+(Y(0)>h-p-14?-6:14));c.fillText(o.yl,X(0)+4,18);c.fillText(f(o.x0,1),p,h-p+14);c.fillText(f(o.x1,1),w-30,h-p+14);c.fillText(f(o.y1,1),2,16);c.fillText(f(o.y0,1),2,h-p);
o.ln.forEach(l=>{c.beginPath();c.strokeStyle=col(l.c);c.lineWidth=l.w||2;c.setLineDash(l.d||[]);l.p.forEach((q,i)=>i?c.lineTo(X(q[0]),Y(q[1])):c.moveTo(X(q[0]),Y(q[1])));c.stroke()});c.setLineDash([]);
(o.dots||[]).forEach(d=>{c.fillStyle=col('ok');c.beginPath();c.arc(X(d[0]),Y(d[1]),7,0,7);c.fill();c.fillStyle=col('ink');c.font='bold 12px system-ui';c.fillText('Q',X(d[0])+10,Y(d[1])-8)})}
const tag=(t,c)=>`<span class="tag" style="background:${col(c)}">${t}</span>`;
/* circuits */
$('c1').innerHTML='<b>Voltage divider</b>'+sl('vi','V in',1,24,.5,10,'V')+sl('r1','R1',.1,20,.1,1,'kΩ')+sl('r2','R2',.1,20,.1,1,'kΩ')+sl('rl','R load (20 = none)',.1,20,.1,20,'kΩ')+'<div id="cv"></div>';
$('c2').innerHTML='<b>Thevenin equivalent seen by the load</b><div id="ct"></div><div class="say">Trick: if R load is much bigger than R<sub>TH</sub>, the load barely disturbs the divider. Lower R load and V out sags.</div>';
function circ(){const v=V('vi'),a=V('r1'),b=V('r2'),l=V('rl'),nl=l>=20,vth=v*b/(a+b),rth=a*b/(a+b),vo=nl?vth:vth*l/(l+rth),I=v/(a+b);
const bar=(t,x,c)=>`<div class="bar" style="width:${Math.max(x/v*100,1)}%;background:${col(c)}">${t}</div>`;
$('cv').innerHTML=bar('V in = '+f(v)+' V',v,'ink')+bar('V on R1 = '+f(v-vth)+' V',v-vth,'red')+bar('V out (no load) = '+f(vth)+' V',vth,'blue')+(nl?'':bar('V out with load = '+f(vo)+' V',vo,'ok'))+`<div class="res">I = Vin/(R1+R2) = ${f(I)} mA<br>P total = ${f(v*I)} mW</div>`;
$('ct').innerHTML=`<div class="res">V<sub>TH</sub> = Vin·R2/(R1+R2) = ${f(vth)} V<br>R<sub>TH</sub> = R1‖R2 = ${f(rth,3)} kΩ<br>V out = ${f(vo)} V<br>I load = ${nl?'0':f(vo/l,3)} mA</div>`}
/* diode */
$('d1').innerHTML='<b>Circuit</b>'+sl('dv','V TH',-20,20,.1,5,'V')+sl('dr','R TH',.1,5,.1,2,'kΩ')+'<p>Diode type</p>'+sel('dt',['Ideal','Silicon 0.7 V','Zener (ideal)','Zener (0.7 V forward)'])+sl('dz','V Z',1,10,.5,5,'V');
function dio(){const vt=V('dv'),R=V('dr'),t=$('dt').selectedIndex,vf=t%2?.7:0,z=t>1,Vz=V('dz');let q,I,m;
if((vt-vf)/R>0){I=(vt-vf)/R;q=vf;m=['ON (forward)','ok']}else if(z&&vt<-Vz){I=(vt+Vz)/R;q=-Vz;m=['ZENER region','red']}else{I=0;q=vt;m=['OFF (blocking)','blue']}
const ext=Math.max(Math.abs(vt),Vz,1)*1.3,ym=Math.max(Math.abs(vt)/R,2)*1.2,ch=[[-ext,z?0:0],[vf,0],[vf,ym]];if(z)ch.splice(0,1,[-Vz,-ym],[-Vz,0]);else ch.unshift([-ext,0]);
plot($('dc'),{x0:-ext,x1:ext,y0:-ym,y1:ym,xl:'V_AK (V)',yl:'I_D (mA)',ln:[{p:ch,c:'blue',w:3},{p:[[vt,0],[0,vt/R]],c:'red',d:[6,4]}],dots:[[q,I]]});
$('dres').innerHTML=`Q point = (V<sub>AK</sub> = ${f(q)} V, I<sub>D</sub> = ${f(I,3)} mA)<br>${tag(m[0],m[1])}`;
$('dsay').innerHTML='Blue = diode curve, dashed red = load line (all circuit solutions). Q is where they cross. Load line points: diode as short → I = V<sub>TH</sub>/R<sub>TH</sub>; as open → V = V<sub>TH</sub>.'}
/* mosfet */
$('m1').innerHTML='<b>Circuit</b>'+sl('mg','V GS',0,12,.5,7.5,'V')+sl('mv','V DD',2,24,1,12,'V')+sl('mr','R D',5,200,5,40,'Ω');
function mos(){const g=V('mg'),vdd=V('mv'),R=V('mr'),vth=2.5,kn=2;let I,vds,m;const isat=g<vth?0:(g-vth)*40,ron=isat?kn/isat*1000:1e9;
if(!isat){I=0;vds=vdd;m=['CUTOFF = open switch','blue']}else if(vdd-isat/1000*R>=kn){I=isat;vds=vdd-I/1000*R;m=['SATURATION = current source','red']}else{I=vdd/(R+ron)*1000;vds=vdd-I/1000*R;m=['OHMIC = closed switch (R_DS(on)='+f(ron)+' Ω)','ok']}
const ym=Math.max(vdd/R*1000,330)*1.1,xm=Math.max(vdd,4)*1.05,ln=[];[5,7.5,10,12].forEach(v=>{const s=(v-vth)*40;ln.push({p:[[0,0],[kn,s],[xm,s]],c:v==g?'blue':'line',w:v==g?3:1.5})});
if(g>=vth&&![5,7.5,10,12].includes(g)){const s=(g-vth)*40;ln.push({p:[[0,0],[kn,s],[xm,s]],c:'blue',w:3})}
ln.push({p:[[0,0],[xm,0]],c:'blue',w:g<vth?3:1.5},{p:[[vdd,0],[0,vdd/R*1000]],c:'red',d:[6,4]});
plot($('mc'),{x0:0,x1:xm,y0:0,y1:ym,xl:'V_DS (V)',yl:'I_D (mA)',ln,dots:[[vds,I]]});
$('mosres').innerHTML=`Q = (V<sub>DS</sub> = ${f(vds)} V, I<sub>D</sub> = ${f(I,1)} mA)<br>P in MOSFET = ${f(vds*I)} mW<br>${tag(m[0],m[1])}`;
$('mossay').innerHTML='Gray = curves for other V<sub>GS</sub>; blue = yours; dashed red = load line. As a switch you want V<sub>GS</sub> high: low V<sub>DS</sub> means little heat in the transistor.'}
/* bjt */
$('b1').innerHTML='<b>Circuit (β = 100)</b>'+sl('bb','V BB',0,10,.1,2,'V')+sl('br','R B',1,100,1,10,'kΩ')+sl('bc','V CC',2,24,1,15,'V')+sl('bcr','R C',.1,5,.1,1,'kΩ')+sl('bbe','β',20,300,10,100,'');
function bjt(){const vbb=V('bb'),rb=V('br'),vcc=V('bc'),rc=V('bcr'),be=V('bbe');let ib=Math.max((vbb-.7)/rb,0),ic=be*ib,vce=vcc-ic*rc,m;
if(ib==0){m=['CUTOFF = open switch','blue']}else if(vce<=0){ic=vcc/rc;vce=0;m=['SATURATION = closed switch (needs I_B > I_C(sat)/β)','red']}else m=['ACTIVE = amplifier zone','ok'];
const ics=vcc/rc,ym=ics*1.2,ln=[],ibl=[...new Set([0.1,.25,.5,.75,1].map(k=>k*ics/be))];ibl.forEach(i=>{const y=Math.min(i*be,ics*1.15);ln.push({p:[[0,0],[.1,y],[vcc*1.05,y]],c:'line',w:1.5})});
if(ib){const y=Math.min(ic,ym);ln.push({p:[[0,0],[.1,y],[vcc*1.05,y]],c:'blue',w:3})}ln.push({p:[[vcc,0],[0,ics]],c:'red',d:[6,4]});
plot($('bcv'),{x0:0,x1:vcc*1.05,y0:0,y1:ym,xl:'V_CE (V)',yl:'I_C (mA)',ln,dots:[[vce,ic]]});
$('bres').innerHTML=`I<sub>B</sub> = (V<sub>BB</sub>−0.7)/R<sub>B</sub> = ${f(ib*1000,1)} µA<br>I<sub>C</sub> = ${f(ic,2)} mA, V<sub>CE</sub> = ${f(vce)} V<br>${tag(m[0],m[1])}`;
$('bsay').innerHTML='Red dashed = load line from V<sub>CC</sub> (cutoff) to V<sub>CC</sub>/R<sub>C</sub> (saturation). Q slides along it when I<sub>B</sub> changes. Switch design: pick I<sub>B</sub> well above I<sub>C</sub>/β.'}
/* rc */
$('rcb').innerHTML='<b>Circuit</b>'+sl('rv','V source',1,24,1,10,'V')+sl('rr','R',1,100,1,10,'kΩ')+sl('rcc','C',1,100,1,10,'µF');
function rc(){const v=V('rv'),R=V('rr'),C=V('rcc'),tau=R*C,N=5*tau,p=[];for(let i=0;i<=60;i++){const t=N*i/60;p.push([t,v*(1-Math.exp(-t/tau))])}
plot($('rcv'),{x0:0,x1:N,y0:0,y1:v*1.05,xl:'t (ms)',yl:'V_C (V)',ln:[{p,c:'blue',w:3},{p:[[tau,0],[tau,v*.632]],c:'red',d:[4,4]}],dots:[[tau,v*.632]]});
$('rres').innerHTML=`τ = R·C = ${f(tau)} ms<br>At 1τ: ${f(v*.632)} V (63%)<br>At 5τ (${f(5*tau)} ms): ${f(v*.993)} V (99%)<br>kΩ·µF = ms`}
/* formulas */
const F=[['Basics','Ohm’s law','V = I·R','Voltage across, current through. R in Ω, I in A.'],['Basics','Power','P = V·I = V²/R = I²·R','Resistors always absorb power. Source P = V·I; negative absorbed power = it delivers.'],['Basics','Units','1 kΩ·1 mA = 1 V','kΩ with mA gives V. MΩ with µF gives seconds; kΩ with µF gives ms.'],['Basics','Series R','R = R1 + R2','Same current. Largest resistor dominates.'],['Basics','Parallel R','1/R = 1/R1 + 1/R2 · R = R1·R2/(R1+R2)','Always smaller than the smallest. Two equal R → half.'],['Basics','Source power sign','Current out of + → source; into + → load','Check with P = V·I: P < 0 means it delivers energy.'],['Laws','KCL','Σ I in = Σ I out','Choose directions, stay consistent. A negative answer = opposite direction.'],['Laws','KVL','Σ V around a loop = 0','Write the first sign you meet on each element. Direction of the walk doesn’t matter.'],['Laws','Voltage divider','Vout = Vin·R2/(R1+R2)','Valid only if nothing loads the output.'],['Laws','Series sources','Sources in series just add (mind the polarity)','Example in your notes: 5 V + 5 V against a 10 V source gives 0 A.'],['Laws','Current source ∥ R','I with R in parallel ≡ V = I·R in series with R','Quick source transformation (10 mA ∥ 1 kΩ ≡ 10 V + 1 kΩ).'],['Theorems','Thevenin','V_TH = V_AB open · R_TH = R seen with sources killed','Voltage source → short, current source → open. Include every element when finding R_TH.'],['Theorems','Thevenin trick','Use it whenever the load changes or a diode/transistor is the only nonlinear part','Reduce the circuit around the diode, then only a series loop remains.'],['Theorems','Superposition','Total = Σ effect of each source alone','Linear circuits only. Turn off the others. Try Thevenin first for each partial circuit.'],['Diodes','Ideal diode','ON: V_D = 0, I_D ≥ 0 · OFF: I_D = 0, V_AK ≤ 0','Sign convention: V_AK = V_A − V_K, I from A to K.'],['Diodes','Real diode','ON: V_D = 0.7 V (silicon)','I = (V_TH − 0.7)/R_TH.'],['Diodes','Zener','Forward ≈ diode · reverse: V_AK = −V_Z when breakdown','In the zener region I_D < 0 and I = (V_TH + V_Z)/R_TH.'],['Diodes','Solve by assumption','1) guess ON/OFF/zener 2) solve 3) check compatibility','OFF needs V_AK < 0; ON needs I_D > 0. If incompatible, change the guess.'],['Diodes','Solve by load line','Two points: diode short (V=0, I=V_TH/R_TH) and open (V=V_TH, I=0)','Q = intersection with the characteristic curve. No assumption needed.'],['Diodes','Quick checks','A diode in series with a current source (pointing forward) is always ON','A diode that is in reverse across a source is OFF. Look before calculating.'],['Diodes','LED resistor','R = (V − V_F)/I_LED','Example: (10 − 2.5)/10 mA = 750 Ω.'],['Diodes','Battery life','t = Capacity (Wh) / P load (W)','Remember zener and resistors consume too, not just the LED.'],['MOSFET','Regions (NMOS)','Cutoff: V_GS < V_th · Ohmic: V_DS < V_ov · Saturation: V_DS > V_ov','V_ov = V_GS − V_th. PMOS: use V_SG and V_SD.'],['MOSFET','Gate','I_G = 0','The oxide is an insulator. A resistive divider on the gate sets V_GS with no loading.'],['MOSFET','R_DS(on)','R_DS(on) = V_DS(on)/I_D(on)','Inverse of the slope in the ohmic region. Used as a switch.'],['MOSFET','Load line','I_D(sat) = V_DD/R_D · V_DS = V_DD − I_D·R_D','Q = intersection with the curve of your V_GS.'],['MOSFET','Switch trick','Drive V_GS well above V_th so it works in the ohmic region','Then P = I²·R_DS(on): little heat. In saturation it dissipates much more.'],['MOSFET','Zener on gate','V_GS = V_Z if the zener conducts','Check the zener region as you would with a diode.'],['BJT','Currents','I_E = I_C + I_B · I_C = β·I_B · I_C ≈ I_E','I_B is tiny compared with I_C.'],['BJT','Base loop (ideal V_BE = 0)','I_B = (V_BB − V_BE)/R_B','Real silicon: V_BE = 0.7 V.'],['BJT','Collector loop','V_CE = V_CC − I_C·R_C','Valid in the active region.'],['BJT','Regions','Cutoff I_B = 0 · Active I_C = β I_B · Saturation V_CE ≈ 0','If β·I_B > I_C(sat), it is saturated: I_C = V_CC/R_C.'],['BJT','Load line','Cutoff (V_CE = V_CC, I_C = 0) · Saturation (V_CE = 0, I_C = V_CC/R_C)','Q moves along it when I_B changes.'],['BJT','Switch design','Force I_B ≥ a few times I_C(sat)/β','Then R_B = (V_in − 0.7)/I_B.'],['Capacitor','Equations','i = C·dv/dt · w = ½·C·V²','V can’t change instantly. Open circuit at DC.'],['Capacitor','Association','Parallel: C = C1 + C2 · Series: 1/C = 1/C1 + 1/C2','Opposite to resistors.'],['Capacitor','RC charge','v(t) = V∞ − (V∞ − V₀)·e^(−t/τ) · τ = R·C','63% at 1τ, 99% at 5τ.'],['Inductor','Equations','v = L·di/dt · w = ½·L·i²','I can’t change instantly. Short circuit at DC. Series add, parallel like resistors.'],['Lab','Resistor colors','Digits, then multiplier, tolerance last (gold 5%, silver 10%)','Black 0 · brown 1 · red 2 · orange 3 · yellow 4 · green 5 · blue 6 · violet 7 · gray 8 · white 9.'],['Lab','Decoupling','100 nF–1 µF close to the IC supply pin','Filters noise on the power supply.'],['Lab','Open vs short','Open: I = 0, V unknown · Short: V = 0, I unknown','Overpower destroys transistors; solder splashes create shorts.']];
function list(){const s=$('q').value.toLowerCase(),k=$('fc').value;let h='',c='';F.forEach(r=>{if((s&&!r.join(' ').toLowerCase().includes(s))||(k&&r[0]!=k))return;if(r[0]!=c){c=r[0];h+=`<h2 style="margin-top:14px;font-size:20px">${c}</h2>`}h+=`<div class="fi"><b>${r[1]}</b><br><span class="f">${r[2]}</span><small>${r[3]}</small>${(EXM[r[0]+r[1]]||EXM[r[1]])?`<small>Example: ${EXM[r[0]+r[1]]||EXM[r[1]]}</small>`:''}</div>`});$('fl').innerHTML=h||'<p>No match. Try “ohm”, “zener” or “tau”.</p>'}
$('q').oninput=list;
/* v2: diagrams, exercises, maker, practice */
const S=b=>`<svg viewBox="0 0 300 150" style="width:100%;max-width:340px;display:block;margin:6px auto;color:var(--ink)" role="img" aria-label="circuit diagram">${b}</svg>`,w=d=>`<path d="${d}" fill="none" stroke="currentColor" stroke-width="2"/>`,tx=(x,y,s)=>`<text x="${x}" y="${y}" font-size="13" text-anchor="middle" fill="currentColor" font-family="system-ui">${s}</text>`,zg=(x,y,r,l)=>`<path transform="translate(${x} ${y}) rotate(${r})" d="M-22,0h6l4,-8l8,16l8,-16l8,16l4,-8h6" fill="none" stroke="var(--red)" stroke-width="2"/>`+tx(r?x+28:x,r?y+4:y-14,l),bt=(x,y,l)=>w(`M${x},${y-22}v18M${x-12},${y-4}h24M${x-7},${y+4}h14M${x},${y+4}v18`)+tx(x-28,y+4,l)+tx(x+10,y-8,'+'),gnd=(x,y)=>w(`M${x-10},${y}h20M${x-6},${y+5}h12M${x-2},${y+10}h4`),ct=(x,y,l)=>`<circle cx="${x}" cy="${y}" r="3" fill="var(--card)" stroke="currentColor" stroke-width="2"/>`+tx(x,y+(y<30?-8:22),l);
const dg={div:()=>S(bt(40,75,'Vin')+w('M40,53V25H108M152,25H200V43M200,87V125H40V97M200,25H250')+zg(130,25,0,'R1')+zg(200,65,90,'R2')+ct(250,25,'Vout')),dio:()=>S(bt(40,75,'V_TH')+w('M40,53V25H108M152,25H220V53M220,97V125H40V97')+zg(130,25,0,'R_TH')+`<g transform="translate(220 75) rotate(90)">${w('M-22,0h14M-8,-9v18l16,-9zM8,-9v18M8,0h14')}</g>`+tx(238,52,'A')+tx(238,106,'K')),mos:()=>S(ct(178,20,'V_DD')+w('M178,24V30M178,74V93H160M160,88V98M160,103V113M160,118V128M152,88V128M100,108H152M160,123H178V132')+zg(178,52,90,'R_D')+ct(100,108,'V_GS')+gnd(178,132)),bjt:()=>S(ct(200,20,'V_CC')+w('M200,24V30M200,74V84L152,98M152,84V124M152,112L200,128V132M30,106H70M114,106H152M193,124l-10,-1M193,124l-5,-9')+zg(200,52,90,'R_C')+zg(92,106,0,'R_B')+ct(30,106,'V_BB')+gnd(200,132)),rc:()=>S(bt(40,75,'V')+w('M40,53V25H108M152,25H200V60M188,60h24M188,70h24M200,70V125H40V97')+zg(130,25,0,'R')+tx(232,68,'C'))};
const L=document.querySelectorAll('#learn details');[[4,'div'],[5,'dio'],[6,'mos'],[6,'bjt'],[7,'rc']].forEach(([i,k])=>L[i].insertAdjacentHTML('beforeend',dg[k]()));
