/* formula upgrade */
const EXM={'Ohm’s law':'12 V across 470 Ω gives 25.5 mA','Power':'5 V on 100 Ω: P = 25/100 = 0.25 W','Parallel R':'1k ‖ 1k = 500 Ω; 1k ‖ 10k = 909 Ω','Voltage divider':'10 V, 1k and 3k: Vout = 10·3/4 = 7.5 V','Thevenin':'Divider 10 V, 1k/1k: V_TH = 5 V, R_TH = 500 Ω','LED resistor':'(10 − 2.5)/10 mA = 750 Ω','R_DS(on)':'0.1 V at 100 mA → 1 Ω','RC charge':'10 kΩ·10 µF = 100 ms; 5τ = 500 ms','Base loop (ideal V_BE = 0)':'(5 − 0.7)/4.3 kΩ = 1 mA','Switch design':'I_C(sat) = 100 mA, β = 100 → I_B ≥ 1 mA; use 2–5 mA','Collector loop':'15 V − 100 mA·100 Ω = 5 V'};
F.push(['Tricks','Check before calculating','Diode in series with a current source (forward) → ON; in reverse across a source → OFF','Saves a page of equations.'],['Tricks','Which resistor wins?','Series: the biggest · Parallel: the smallest','100 Ω ‖ 10 kΩ ≈ 99 Ω.'],['Tricks','Sanity check','V_out ≤ V_in (divider) · V_DS ≤ V_DD · V_CE ≤ V_CC','If not, an assumption or a sign is wrong.'],['Tricks','Negative result?','You guessed the direction backwards; the math is still right','For a diode, a wrong sign means a wrong ON/OFF assumption.'],['Tricks','Guess the zener','Remove it, compute V_KA; if ≥ V_Z it conducts in reverse','Check forward first when V_TH is positive at the anode.'],['Tricks','Universal recipe','1) simplify with Thevenin 2) assume or draw the load line 3) verify 4) compute power','Works for diodes, MOSFETs and BJTs.'],['Tricks','Common mistakes','Not killing sources for R_TH · mixing kΩ with A · wrong V_AK sign · wrong terminals for Thevenin','kΩ·mA = V, V/kΩ = mA.'],['Tricks','Power budget','MOSFET: P = V_DS·I_D · BJT: P ≈ V_CE·I_C','Switch fully ON ⇒ small V ⇒ cool transistor.']);
