function addRow(t='R',a=1,b=0,v=1){$('krows').insertAdjacentHTML('beforeend',`<div class="krow"><select aria-label="type">${'RVIDZ'.split('').map(x=>`<option${x==t?' selected':''}>${x}</option>`).join('')}</select><input type="number" value="${a}" aria-label="node a"><input type="number" value="${b}" aria-label="node b"><input type="number" step="any" value="${v}" aria-label="value"><button class="b" aria-label="delete" onclick="this.parentNode.remove();draw()">×</button></div>`)}
