function kload(){$('krows').innerHTML='';PRE[$('kpre').value][1].forEach(r=>addRow(...r))}
function mna(els,st){const n=Math.max(0,...els.flatMap(e=>[e.a,e.b])),vs=[];els.forEach((e,i)=>{if(e.t=='V'||(e.t=='D'&&st[i]==1))vs.push([e.a,e.b,e.v,i]);else if(e.t=='Z'&&st[i]>0)vs.push([e.a,e.b,st[i]==1?0:-e.v,i])});const N=n+vs.length,A=Array.from({length:N},()=>Array(N+1).fill(0)),ad=(r,c,x)=>{if(r>0&&c>0)A[r-1][c-1]+=x};els.forEach(e=>{if(e.t=='R'){const G=1/e.v;ad(e.a,e.a,G);ad(e.b,e.b,G);ad(e.a,e.b,-G);ad(e.b,e.a,-G)}else if(e.t=='I'){if(e.a>0)A[e.a-1][N]-=e.v;if(e.b>0)A[e.b-1][N]+=e.v}});vs.forEach(([a,b,v],k)=>{const c=n+k;if(a>0){A[a-1][c]+=1;A[c][a-1]+=1}if(b>0){A[b-1][c]-=1;A[c][b-1]-=1}A[c][N]=v});for(let i=0;i<N;i++){let p=i;for(let r=i+1;r<N;r++)if(Math.abs(A[r][i])>Math.abs(A[p][i]))p=r;if(Math.abs(A[p][i])<1e-12)return null;[A[i],A[p]]=[A[p],A[i]];for(let r=0;r<N;r++)if(r!=i){const k=A[r][i]/A[i][i];for(let c=i;c<=N;c++)A[r][c]-=k*A[i][c]}}const x=A.map((r,i)=>r[N]/r[i]);return{V:[0,...x.slice(0,n)],J:x.slice(n),vs}}
function mkSolve(){const els=netList(),out=$('kres');if(!els.length){out.innerHTML='';$('kdraw').innerHTML='';return}
const dI=els.map((e,i)=>'DZ'.includes(e.t)?i:-1).filter(i=>i>=0),K=Math.min(dI.length,7);let best=null;if(!els.some(e=>e.t=='R'&&e.v<=0))for(let c=0;c<3**K&&!best;c++){const st=[];let cc=c,bad=0;dI.forEach((i,q)=>{st[i]=q<K?cc%3:0;cc=Math.floor(cc/3);if(els[i].t=='D'&&st[i]==2)bad=1});if(bad)continue;const s=mna(els,st);if(!s)continue;const tol=1e-9;if(dI.every(i=>{const e=els[i],vd=s.V[e.a]-s.V[e.b],q=s.vs.findIndex(u=>u[3]==i),j=q<0?0:s.J[q];if(e.t=='D')return st[i]==1?j>=-tol:vd<=e.v+tol;return st[i]==1?j>=-tol:st[i]==2?j<=tol:(vd<=tol&&vd>=-e.v-tol)}))best={s,st}}
if(!best){out.innerHTML='<div class="res">No solution. Check that every node reaches ground (0), R &gt; 0 and there is no loop of ideal voltage sources.</div>';$('kdraw').innerHTML='';return}
const{s,st}=best,vv=s.V,ro=els.map((e,i)=>{const d=vv[e.a]-vv[e.b],q=s.vs.findIndex(u=>u[3]==i),I=e.t=='R'?d/e.v:e.t=='I'?e.v:q<0?0:s.J[q];return{e,d,I,P:d*I,m:'DZ'.includes(e.t)?['OFF','ON','ZENER'][st[i]]:''}});
out.innerHTML='<div class="res">'+vv.map((x,k)=>`N${k}${k?'':' (ground)'}: ${f(x,3)} V`).join('<br>')+'</div><div class="res">'+ro.map(r=>`${r.e.n}: V=${f(r.d,3)} V, I=${f(r.I,3)} mA, P=${f(r.P,3)} mW ${r.m?tag(r.m,r.m=='OFF'?'blue':r.m=='ON'?'ok':'red'):r.P<-1e-9?'(delivers)':''}`).join('<br>')+`<br>Σ P = ${f(ro.reduce((a,r)=>a+r.P,0),6)} mW (always 0)</div>`;
const n=vv.length,P=k=>[150+100*Math.cos(Math.PI/2+6.2832*k/n),115+80*Math.sin(Math.PI/2+6.2832*k/n)],cnt={};let g='';ro.forEach(r=>{const{a,b,t,v}=r.e,key=Math.min(a,b)+'-'+Math.max(a,b),i=cnt[key]=(cnt[key]||0)+1,[x0,y0]=P(a),[x1,y1]=P(b),dx=x1-x0,dy=y1-y0,l=Math.hypot(dx,dy)||1,o=(i-1)*34*(i%2?1:-1)*(a<b?1:-1)*0+((i-1)*(i%2?1:-1)*Math.ceil((i-1)/2+.5)*28),cx=(x0+x1)/2-dy/l*o,cy=(y0+y1)/2+dx/l*o,c=t=='R'?'red':t=='V'?'blue':t=='I'?'ok':'mut';g+=`<path d="M${x0},${y0}Q${cx},${cy} ${x1},${y1}" fill="none" stroke="var(--${c})" stroke-width="2.5"/>`+`<text x="${(x0+x1)/4+cx/2}" y="${(y0+y1)/4+cy/2}" font-size="11" text-anchor="middle" fill="var(--${c})" font-weight="700">${t}${t=='R'?v+'k':t=='I'?v+'mA':v+'V'}</text>`});
vv.forEach((x,k)=>{const[px,py]=P(k);g+=`<circle cx="${px}" cy="${py}" r="13" fill="var(--card)" stroke="currentColor" stroke-width="2"/><text x="${px}" y="${py+4}" font-size="12" text-anchor="middle" fill="currentColor">${k}</text><text x="${px}" y="${py+(py>115?28:-19)}" font-size="11" text-anchor="middle" fill="currentColor">${f(x,2)} V</text>`});$('kdraw').innerHTML=`<svg viewBox="0 0 300 245" style="width:100%;color:var(--ink)" role="img" aria-label="circuit graph">${g}</svg>`;$('kdraw').innerHTML=schem(ro,vv)}
