const pk=a=>a[Math.random()*a.length|0],mosQ=(g,vdd,R)=>{const s=g<2.5?0:(g-2.5)*40;if(!s)return[0,vdd];if(vdd-s*R/1000>=2)return[s,vdd-s*R/1000];const I=vdd/(R+2/s*1000)*1000;return[I,vdd-I*R/1000]};
const TOP={ohm:'Ohm’s law',pow:'Power',div:'Voltage divider',par:'Parallel resistors',thev:'Thevenin with a load',dio:'Diode operation point',led:'LED resistor',mos:'MOSFET',bjt:'BJT',rc:'RC circuit'};
const GEN={ohm:()=>{const v=pk([5,9,12,24]),r=pk([100,220,470,1000,2200]);return{q:`A ${v} V source is across a ${r} Ω resistor. Current in mA?`,a:v/r*1000,s:`I = V/R = ${v}/${r} = ${f(v/r*1000,3)} mA`}},pow:()=>{const v=pk([5,9,12]),r=pk([100,220,470,1000]);return{q:`A ${r} Ω resistor has ${v} V across it. Power in mW?`,a:v*v/r*1000,s:`P = V²/R = ${v*v}/${r} = ${f(v*v/r*1000,2)} mW`}},div:()=>{const v=pk([5,10,12,15]),a=pk([1,2,4.7,10]),b=pk([1,2.2,3.3,10]);return{g:'div',q:`Divider: Vin = ${v} V, R1 = ${a} kΩ (top), R2 = ${b} kΩ (bottom). Vout across R2 in V (no load)?`,a:v*b/(a+b),s:`Vout = Vin·R2/(R1+R2) = ${v}·${b}/${f(a+b)} = ${f(v*b/(a+b),3)} V`}},par:()=>{const a=pk([1,2.2,4.7,10]),b=pk([1,3.3,6.8,22]);return{q:`R1 = ${a} kΩ in parallel with R2 = ${b} kΩ. Equivalent in kΩ?`,a:a*b/(a+b),s:`R = R1·R2/(R1+R2) = ${f(a*b)}/${f(a+b)} = ${f(a*b/(a+b),3)} kΩ`}},thev:()=>{const v=pk([6,10,12,20]),a=pk([1,2,4.7]),b=pk([1,2,3.3,10]),l=pk([1,2,5,10]),vt=v*b/(a+b),rt=a*b/(a+b);return{g:'div',q:`Divider Vin = ${v} V, R1 = ${a} kΩ, R2 = ${b} kΩ, and a load R_L = ${l} kΩ on the output (across R2). V_L in V?`,a:vt*l/(l+rt),s:`V_TH = ${f(vt,3)} V, R_TH = R1‖R2 = ${f(rt,3)} kΩ. V_L = V_TH·R_L/(R_L+R_TH) = ${f(vt*l/(l+rt),3)} V`}},dio:()=>{const v=pk([-5,3,5,9,12]),r=pk([1,2,4.7]),vf=pk([0,.7]);const I=Math.max((v-vf)/r,0);return{g:'dio',q:`Thevenin equivalent V_TH = ${v} V, R_TH = ${r} kΩ, diode ${vf?'with V_F = 0.7 V':'ideal'}. Diode current in mA?`,a:I,s:v-vf>0?`Forward: I = (V_TH − V_F)/R_TH = (${v} − ${vf})/${r} = ${f(I,3)} mA`:`V_TH − V_F ≤ 0 → diode OFF, I = 0 mA`}},led:()=>{const v=pk([5,9,12]),vf=pk([1.8,2,2.5,3]),i=pk([10,20,100]);return{q:`${v} V supply, LED V_F = ${vf} V, desired current ${i} mA. Series resistor in Ω?`,a:(v-vf)/i*1000,s:`R = (V − V_F)/I = ${f(v-vf)}/${i} mA = ${f((v-vf)/i*1000,1)} Ω`}},mos:()=>{const g=pk([1,2,5,7.5,10]),vdd=pk([5,12,24]),R=pk([20,50,100]),[I]=mosQ(g,vdd,R);return{g:'mos',q:`NMOS, V_GS = ${g} V, V_DD = ${vdd} V, R_D = ${R} Ω. Model: cutoff below 2.5 V, saturation current 40 mA per volt above 2.5 V, knee at 2 V. I_D in mA?`,a:I,s:g<2.5?'V_GS below 2.5 V: cutoff, I_D = 0':`I_sat = ${f((g-2.5)*40)} mA. Try saturation: V_DS = ${vdd} − ${f((g-2.5)*40*R/1000,2)} V. ${vdd-(g-2.5)*40*R/1000>=2?'≥ 2 V → saturation, I_D = I_sat.':'< 2 V → ohmic: R_on = 2 V/I_sat, I = V_DD/(R_D+R_on) = '+f(I,2)+' mA.'}`}},bjt:()=>{const vbb=pk([2,3,5,9]),rb=pk([4.7,10,22,47]),vcc=pk([9,12,15]),rc=pk([.1,.22,.47,1]),be=pk([50,100,200]),ib=(vbb-.7)/rb,ic=Math.min(be*ib,vcc/rc);return{g:'bjt',q:`NPN, β = ${be}, V_BB = ${vbb} V, R_B = ${rb} kΩ, V_CC = ${vcc} V, R_C = ${rc} kΩ (V_BE = 0.7 V). I_C in mA?`,a:ic,s:`I_B = (${vbb} − 0.7)/${rb} = ${f(ib*1000,1)} µA, β·I_B = ${f(be*ib,2)} mA vs I_C(sat) = V_CC/R_C = ${f(vcc/rc,2)} mA → ${be*ib>vcc/rc?'saturated, I_C = '+f(vcc/rc,2):'active, I_C = β·I_B = '+f(be*ib,2)} mA`}},rc:()=>{const r=pk([1,4.7,10,22]),c=pk([1,10,47,100]),v=pk([5,10]);return{g:'rc',q:`R = ${r} kΩ, C = ${c} µF charging from 0 V to ${v} V. Time to reach 63% (τ) in ms?`,a:r*c,s:`τ = R·C = ${r} kΩ · ${c} µF = ${r*c} ms (kΩ·µF = ms)`}}};
