$('krows').addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;const i=+t.dataset.i;if(t.dataset.f=='del')ST.splice(i,1);else ST[i].flip=!ST[i].flip;stRender();draw()});
$('kvin').addEventListener('input',()=>{VIN=+$('kvin').value||0});
$('kadd').onclick=()=>{ST.push({k:'ser',t:'R',v:1,flip:false});stRender();draw()};$('kadd2').onclick=()=>{ST.push({k:'sh',t:'R',v:1,flip:false});stRender();draw()};
function ksel(){const p=SP[$('kpre').value];VIN=p[1];$('kvin').value=VIN;ST=p[2].map(r=>({k:r[0],t:r[1],v:r[2],flip:!!r[3]}));stRender()}$('kpre').onchange=()=>{ksel();draw()};ksel();
function netList(){const E=[{t:'V',a:1,b:0,v:VIN,n:'Vin'}];let c=1,n=1;ST.forEach((s,i)=>{const t=s.t=='L'?'D':s.t;let a,b;if(s.k=='ser'){n++;[a,b]=(s.t=='V'?!s.flip:s.flip)?[n,c]:[c,n];c=n}else[a,b]=(s.t=='Z'?!s.flip:s.flip)?[0,c]:[c,0];E.push({t,a,b,v:s.v,n:NAME[s.t]+(i+1)})});return E}
function schem(ro,vv){const yT=46,yB=196,yM=121,tx2=(x,y,s,cl,z,an)=>`<text x="${x}" y="${y}" font-size="${z||11}" text-anchor="${an||'middle'}" fill="var(--${cl||'ink'})" font-weight="700">${s}</text>`,val=s=>s.t=='R'?s.v+'k':s.t=='I'?s.v+'mA':s.t=='D'&&!s.v?'ideal':s.v+'V',E=netList();let x=100,c=1,nn=1,g='',tp=`M60,${yT}H100`,bt2=`M60,${yB}H100`;
const dot=(x,k)=>`<circle cx="${x}" cy="${yT}" r="4" fill="currentColor"/>`+tx2(x,yT-12,`N${k} ${f(vv[k],2)}V`,'mut',10);g+=dot(100,1);
ST.forEach((s,i)=>{const r=ro[i+1],e=E[i+1],cl=CM[s.t],tag2=r.m?` ${r.m}`:'';if(s.k=='ser'){const cx=x+55,rot=(s.t=='V'?180:0)+(s.flip?180:0),sg=e.a==c?1:-1,sh=r.I*sg;tp+=`M${x},${yT}H${cx-22}M${cx+22},${yT}H${x+110}`;bt2+=`M${x},${yB}H${x+110}`;g+=sym(s.t,cx,yT,rot,cl)+tx2(cx,yT-28,NAME[s.t]+(i+1)+' '+val(s),cl,12)+tx2(cx,yT+32,`${f(Math.abs(sh),2)} mA ${sh>=0?'→':'←'}${tag2}`,'ink',11);x+=110;c=++nn;g+=dot(x,c)}else{const cx=x+40,rot=(s.t=='Z'?-90:90)+(s.flip?180:0),sg=e.a==c?1:-1,sh=r.I*sg;tp+=`M${x},${yT}H${x+100}`;bt2+=`M${x},${yB}H${x+100}`;g+=`<path d="M${cx},${yT}V${yM-22}M${cx},${yM+22}V${yB}" fill="none" stroke="currentColor" stroke-width="2"/><circle cx="${cx}" cy="${yT}" r="3" fill="currentColor"/><circle cx="${cx}" cy="${yB}" r="3" fill="currentColor"/>`+sym(s.t,cx,yM,rot,cl)+tx2(cx+18,yM-4,NAME[s.t]+(i+1)+' '+val(s),cl,12,'start')+tx2(cx+18,yM+12,`${f(Math.abs(sh),2)} mA ${sh>=0?'↓':'↑'}`,'ink',11,'start')+(r.m?tx2(cx+18,yM+27,r.m,cl,11,'start'):'');x+=100}});
const W=x+50;return `<svg width="${W}" height="235" viewBox="0 0 ${W} 235" style="color:var(--ink)" role="img" aria-label="circuit schematic"><path d="${tp}${bt2}M60,${yT}V${yM-22}M60,${yM+22}V${yB}" fill="none" stroke="currentColor" stroke-width="2"/>${gnd(60,yB)}${sym('V',60,yM,90,'ok')}${tx2(24,yM-2,'Vin','ok',12)}${tx2(24,yM+14,VIN+' V','ok',12)}${g}<circle cx="${x}" cy="${yT}" r="5" fill="var(--card)" stroke="currentColor" stroke-width="2"/>${tx2(x+20,yT+4,'out','mut',11)}</svg>`}
/* game: Crack the Q */
const hs=s=>{let h=7;for(const ch of s)h=Math.imul(h^ch.charCodeAt(0),2654435761);return h>>>0},rngF=a=>()=>{a=a+1831565813|0;let t=Math.imul(a^a>>>15,1|a);t^=t+Math.imul(t^t>>>7,61|t);return((t^t>>>14)>>>0)/4294967296},REG={dio:['OFF','ON','ZENER'],mos:['Cutoff','Ohmic','Saturation'],bjt:['Cutoff','Active','Saturation']};
function puz(k,r){const p=a=>a[r()*a.length|0];if(k=='dio'){const vt=p([-9,-6,-2,4,8,12]),R=p([1,2,4.7]),kd=p([0,1,2]),Vz=p([3.3,5,6.8]),vf=kd==1?.7:0;let reg=0,I=0,v=vt;if((vt-vf)/R>0){reg=1;I=(vt-vf)/R;v=vf}else if(kd==2&&vt<-Vz){reg=2;I=(vt+Vz)/R;v=-Vz}return{kind:k,g:'dio',reg,I,v,txt:`Thevenin: V_TH = ${vt} V, R_TH = ${R} kΩ. Diode: ${['ideal','silicon, V_F = 0.7 V',`ideal zener, V_Z = ${Vz} V`][kd]}. Find the region, I_D (mA) and V_AK (V).`,hint:`Load line: diode as a short → I = V_TH/R_TH = ${f(vt/R,2)} mA; as an open circuit → V = ${vt} V.`,les:'Remove the diode and look at V_TH. If V_TH − V_F > 0 it conducts (ON, I = (V_TH − V_F)/R_TH). If V_TH is below −V_Z a zener breaks down (V = −V_Z). Otherwise it is OFF and all of V_TH appears across it.'}}
if(k=='mos'){const g=p([1,2,4,5,7.5,10]),vd=p([5,12,24]),R=p([20,50,100]),[I,v]=mosQ(g,vd,R),reg=g<2.5?0:vd-(g-2.5)*40*R/1000>=2?2:1;return{kind:k,g:'mos',reg,I,v,txt:`NMOS: V_GS = ${g} V, V_DD = ${vd} V, R_D = ${R} Ω. Curves: cutoff below 2.5 V, I_sat = 40 mA per volt above 2.5 V, knee at 2 V. Find the region, I_D (mA) and V_DS (V).`,hint:`Load line: I_D(sat) = V_DD/R_D = ${f(vd/R*1000,1)} mA, V_DS(open) = ${vd} V. This V_GS gives I_sat = ${f(Math.max(g-2.5,0)*40,1)} mA.`,les:'First compare V_GS with 2.5 V (cutoff). Otherwise try saturation: V_DS = V_DD − I_sat·R_D. If it is ≥ 2 V you are in saturation; if not, you are ohmic and I = V_DD/(R_D + R_on) with R_on = 2 V/I_sat.'}}
const vb=p([.3,2,3,5,9]),rb=p([4.7,10,22,47]),vc=p([9,12,15]),rc2=p([.1,.22,.47,1]),be=p([50,100,200]),ib=Math.max((vb-.7)/rb,0),sat=be*ib>=vc/rc2,reg=ib==0?0:sat?2:1,I=reg==0?0:sat?vc/rc2:be*ib;return{kind:k,g:'bjt',reg,I,v:vc-I*rc2,txt:`NPN: β = ${be}, V_BB = ${vb} V, R_B = ${rb} kΩ, V_CC = ${vc} V, R_C = ${rc2} kΩ, V_BE = 0.7 V. Find the region, I_C (mA) and V_CE (V).`,hint:`Load line: I_C(sat) = V_CC/R_C = ${f(vc/rc2,2)} mA and V_CE(cutoff) = ${vc} V.`,les:'I_B = (V_BB − 0.7)/R_B (zero if V_BB < 0.7). Compare β·I_B with V_CC/R_C: bigger → saturation (V_CE ≈ 0), smaller → active with V_CE = V_CC − I_C·R_C.'}}
let G=null;function gBoard(){let h='';for(let i=0;i<6;i++){const w=G.rows[i];h+='<div class="tl">'+(w?w.map(c=>`<div class="t ${c[0]}">${c[1]}</div>`).join(''):'<div class="t e">region</div><div class="t e">I</div><div class="t e">V</div>')+'</div>'}$('gbd').innerHTML=h}
function gStart(){const t=$('gtop').value,ds=new Date().toISOString().slice(0,10),r=$('gmode').value=='daily'?rngF(hs(ds+t)):Math.random,k=t=='any'?['dio','mos','bjt'][r()*3|0]:t;G={p:puz(k,r),rows:[],done:0,day:ds};$('gdg').innerHTML=dg[G.p.g]();$('gtxt').textContent=G.p.txt;$('greg').innerHTML=REG[k].map((x,i)=>`<option value="${i}">${x}</option>`).join('');$('gmsg').innerHTML='';gBoard();gStat()}
function gStat(u){try{const s=JSON.parse(localStorage.getItem('qq')||'{"p":0,"w":0,"s":0}');if(u){s.p++;if(u>0){s.w++;s.s++}else s.s=0;localStorage.setItem('qq',JSON.stringify(s))}$('gst').textContent=`Played ${s.p} · Cracked ${s.w} · Streak ${s.s}`}catch(e){}}
$('gnew').onclick=gStart;$('gmode').onchange=gStart;$('gtop').onchange=gStart;$('ghint').onclick=()=>{if(G)$('gmsg').innerHTML=`<div class="say">💡 ${G.p.hint}</div>`};
$('gsub').onclick=()=>{if(!G||G.done||$('gi').value===''||$('gv').value==='')return;const p=G.p,gr=+$('greg').value,T=(a,b)=>{const d=Math.abs(a-b),c=d<=Math.max(.05*Math.abs(b),.05)?'g':d<=Math.max(.25*Math.abs(b),.5)?'y':'x';return[c,f(a,2)+(c=='g'?'':a<b?' ▲':' ▼')]},row=[[gr==p.reg?'g':'x',REG[p.kind][gr]],T(+$('gi').value,p.I),T(+$('gv').value,p.v)];G.rows.push(row);gBoard();$('gi').value=$('gv').value='';const win=row.every(c=>c[0]=='g');if(win||G.rows.length>=6){G.done=1;const share=`Crack the Q ${G.day} ${win?G.rows.length:'X'}/6\n`+G.rows.map(r=>r.map(c=>({g:'🟩',y:'🟨',x:'⬛'}[c[0]])).join('')).join('\n');$('gmsg').innerHTML=`<div class="res">${win?tag('Cracked!','ok'):tag('Not this time','red')}<br>Answer: ${REG[p.kind][p.reg]}, I = ${f(p.I,3)} mA, V = ${f(p.v,3)} V<br>${p.les}</div><button class="b" id="gshare">Copy result</button>`;$('gshare').onclick=()=>{try{navigator.clipboard.writeText(share);$('gshare').textContent='Copied!'}catch(e){}};gStat(win?1:-1)}};
gStart();
/* examples for every formula */
Object.assign(EXM,{'Units':'4.7 kΩ across 10 V → 10/4.7 = 2.13 mA','Series R':'1k + 2.2k + 4.7k = 7.9 kΩ','Source power sign':'5 V battery with 2 mA entering its +: P = 5·2 = +10 mW → it absorbs (it is charging)','KCL':'3 mA and 2 mA enter a node → 5 mA must leave','KVL':'10 V source, drops of 4 V and 6 V: −10 + 4 + 6 = 0','Series sources':'5 V + 5 V against a 10 V source → 0 V, no current','Current source ‖ R':'10 mA ‖ 1 kΩ ≡ 10 V in series with 1 kΩ','Thevenin trick':'Divider 10 V, 1k/1k feeding a diode: replace the divider by 5 V + 500 Ω first','Superposition':'Solve once with only V1 on, once with only V2 on, then add the results','Ideal diode':'V_AK = −3 V → OFF, I = 0. 2 mA forward → ON, V = 0','Real diode':'V_TH = 5 V, R_TH = 2 kΩ → I = 4.3/2 = 2.15 mA','Zener':'V_TH = −8 V, V_Z = 5 V, R_TH = 1 kΩ → I = (−8+5)/1 = −3 mA','Solve by assumption':'Guess ON → I = −1 mA (negative!) → wrong guess, the diode is OFF','Solve by load line':'V_TH = 5 V, R_TH = 2k → points (5 V, 0) and (0, 2.5 mA)','Quick checks':'10 mA source feeding a forward diode → ON, no math needed','Battery life':'100 Wh at 1.125 W → 89 h','Regions (NMOS)':'V_GS = 1.4 V below the threshold → cutoff','Gate':'Gate divider 10k/1k from 15 V: V_GS = 15·1/11 = 1.36 V','MOSFETLoad line':'V_DD = 12 V, R_D = 40 Ω → I_D(sat) = 300 mA, V_DS(open) = 12 V','Switch trick':'R_DS(on) = 0.5 Ω at 100 mA → P = 0.1²·0.5 = 5 mW','Zener on gate':'5 V zener conducting across the gate → V_GS = 5 V','Currents':'I_B = 1 mA, β = 100 → I_C = 100 mA, I_E = 101 mA','Regions':'I_B = 1 mA, β = 100, I_C(sat) = 50 mA → saturated','BJTLoad line':'V_CC = 15 V, R_C = 300 Ω → I_C(sat) = 50 mA, V_CE(cutoff) = 15 V','CapacitorEquations':'10 µF with a constant 1 mA → dv/dt = 100 V/s','CapacitorAssociation':'1 µF ‖ 2 µF = 3 µF; two 1 µF in series = 0.5 µF','InductorEquations':'L = 10 mH, di/dt = 100 A/s → v = 1 V','Resistor colors':'Brown–black–red–gold = 10 × 100 = 1 kΩ ±5%','Decoupling':'A 100 nF capacitor next to each IC supply pin','Open vs short':'A burnt resistor is open: I = 0 and the whole supply appears across it','Which resistor wins?':'100 Ω ‖ 10 kΩ ≈ 99 Ω; 100 Ω + 10 kΩ ≈ 10.1 kΩ','Check before calculating':'10 mA source into a forward diode → ON, skip the equations','Sanity check':'A divider giving 12 V from a 10 V input means a mistake','Negative result?':'I = −2 mA on a diode assumed ON → it is really OFF','Guess the zener':'V_KA would be 3.3 V with V_Z = 5 V → not conducting','Universal recipe':'Diode: Thevenin → guess ON → I = 2.15 mA > 0 ✓ → P = 0.7·2.15 = 1.5 mW','Common mistakes':'Forgetting to short the source: 10 V + 1k/1k gives R_TH = 1k instead of 500 Ω','Power budget':'V_CE = 5 V at 100 mA → 0.5 W, check the transistor rating'});
/* step-by-step solver */
const E12=[1,1.2,1.5,1.8,2.2,2.7,3.3,3.9,4.7,5.6,6.8,8.2],e12=r=>{const d=10**Math.floor(Math.log10(r)),m=r/d;return(E12.find(e=>e>=m-1e-9)||10)*d};
const SOL={div:{n:'Voltage divider output',a:'“Find V_out”, “voltage across R2”, “what voltage does the next stage get?”',F:[['vi','Vin (V)',10],['r1','R1 (kΩ)',1],['r2','R2 (kΩ)',3]],S:v=>{const I=v.vi/(v.r1+v.r2);return{s:[['Check what is in series','R1 and R2 carry the same current (nothing else hangs on the middle node).','That is the condition for a divider.'],['Total current',`I = Vin/(R1+R2) = ${f(v.vi)}/${f(v.r1+v.r2)} = ${f(I,3)} mA`,'kΩ with V gives mA.'],['Voltage across R2',`V_out = I·R2 = ${f(I,3)}·${f(v.r2)} = ${f(I*v.r2,3)} V`,'Same as Vin·R2/(R1+R2).'],['Sanity check',`V_out ${f(I*v.r2,2)} V ≤ Vin ${f(v.vi)} V ✓`,'A divider never gives more than the input.']],a:`V_out = ${f(I*v.r2,3)} V`}}},
thev:{n:'Thevenin + load current',a:'“Replace by its Thevenin equivalent”, “current through R_L”, “what if R_L changes?”',F:[['vi','Vin (V)',10],['r1','R1 (kΩ)',1],['r2','R2 (kΩ)',1],['rl','Load R_L (kΩ)',1]],S:v=>{const vt=v.vi*v.r2/(v.r1+v.r2),rt=v.r1*v.r2/(v.r1+v.r2),I=vt/(rt+v.rl);return{s:[['Open the load',`V_TH = Vin·R2/(R1+R2) = ${f(vt,3)} V`,'Voltage between A and B with nothing attached.'],['Kill the sources',`R_TH = R1‖R2 = ${f(rt,3)} kΩ`,'Voltage source → wire, then look into A–B.'],['Draw the equivalent','V_TH in series with R_TH, then R_L.','Now it is a one-loop circuit.'],['Load current',`I_L = V_TH/(R_TH+R_L) = ${f(vt,3)}/${f(rt+v.rl,3)} = ${f(I,3)} mA`,'Change R_L and only this step changes.'],['Load voltage and power',`V_L = I_L·R_L = ${f(I*v.rl,3)} V, P_L = ${f(I*I*v.rl,3)} mW`,'']],a:`V_TH = ${f(vt,3)} V, R_TH = ${f(rt,3)} kΩ, I_L = ${f(I,3)} mA`}}},
eq:{n:'Equivalent resistance',a:'“Find R_eq”, “total current drawn from the source”',F:[['r1','R1 (kΩ)',1],['r2','R2 (kΩ)',2],['r3','R3 (kΩ)',2],['vs','Source (V)',10]],S:v=>{const rp=v.r2*v.r3/(v.r2+v.r3),rt=v.r1+rp,I=v.vs/rt,vp=I*rp;return{s:[['Find what is in parallel','R2 and R3 share the same two nodes (R1 is in series with them).','Always start with the parallel part.'],['Parallel part',`R2‖R3 = R2·R3/(R2+R3) = ${f(rp,3)} kΩ`,'Always smaller than the smallest one.'],['Add the series',`R_eq = R1 + R2‖R3 = ${f(rt,3)} kΩ`,'Series resistors add.'],['Total current',`I = Vs/R_eq = ${f(v.vs)}/${f(rt,3)} = ${f(I,3)} mA`,'Ohm’s law.'],['Voltage on the parallel part',`V = I·(R2‖R3) = ${f(vp,3)} V`,'Then split into branches.'],['Branch currents',`I2 = ${f(vp/v.r2,3)} mA, I3 = ${f(vp/v.r3,3)} mA`,'Check: I2 + I3 = I.']],a:`R_eq = ${f(rt,3)} kΩ, I = ${f(I,3)} mA`}}},
kcl:{n:'Two sources: KCL + KVL',a:'“Find I1, I2, I3” in a circuit with two batteries sharing a branch',F:[['v1','V1 (V)',10],['r1','R1 (Ω)',10],['v2','V2 (V)',20],['r3','R3 (Ω)',20],['r2','R2 shared (Ω)',40]],S:v=>{const Va=(v.v1/v.r1+v.v2/v.r3)/(1/v.r1+1/v.r2+1/v.r3),i1=(v.v1-Va)/v.r1,i3=(v.v2-Va)/v.r3,i2=Va/v.r2;return{s:[['Choose directions','I1 and I3 flow into node A, I2 flows out through R2 to ground.','Any choice works if you stay consistent. A negative result means the real direction is opposite.'],['KCL at A','I1 + I3 = I2','Currents in = currents out.'],['KVL on each loop','−V1 + I1·R1 + I2·R2 = 0 and −V2 + I3·R3 + I2·R2 = 0','Each drop is I·R.'],['Shortcut: voltage at node A',`V_A = (V1/R1 + V2/R3)/(1/R1 + 1/R2 + 1/R3) = ${f(Va,3)} V`,'It packs the equations into one.'],['Currents',`I1 = (V1−V_A)/R1 = ${f(i1,4)} A · I3 = (V2−V_A)/R3 = ${f(i3,4)} A · I2 = V_A/R2 = ${f(i2,4)} A`,'With Ω and V you get A.'],['Check KCL',`I1 + I3 = ${f(i1+i3,4)} and I2 = ${f(i2,4)} ✓`,'Always verify.']],a:`I1 = ${f(i1,4)} A, I2 = ${f(i2,4)} A, I3 = ${f(i3,4)} A`}}},
dio:{n:'Diode operation point',a:'“Find the Q point”, “is the diode ON?”, “determine the operation point of the diodes”',F:[['vth','V_TH (V)',5],['rth','R_TH (kΩ)',2],['kind','Diode: 0 ideal, 1 silicon 0.7 V, 2 zener',1],['vz','Zener V_Z (V)',5]],S:v=>{const vf=v.kind==1?.7:0,z=v.kind==2,a=(v.vth-vf)/v.rth;let reg='OFF',I=0,Vd=v.vth;if(a>0){reg='ON';I=a;Vd=vf}else if(z&&v.vth<-v.vz){reg='ZENER';I=(v.vth+v.vz)/v.rth;Vd=-v.vz}return{s:[['Reduce the circuit',`Everything around the diode becomes V_TH in series with R_TH (Thevenin). Here V_TH = ${f(v.vth)} V, R_TH = ${f(v.rth)} kΩ.`,'The diode is then alone in a single loop.'],['First guess',reg=='ON'?`V_TH − V_F = ${f(v.vth-vf,2)} V > 0: the source pushes current forward → guess ON`:reg=='ZENER'?`V_TH = ${f(v.vth)} V is below −V_Z = ${f(-v.vz)} V → guess ZENER breakdown`:`V_TH − V_F = ${f(v.vth-vf,2)} V ≤ 0 → guess OFF`,'Look at what sign the source pushes on the anode.'],['Solve with that guess',reg=='ON'?`I = (V_TH − V_F)/R_TH = (${f(v.vth)} − ${f(vf)})/${f(v.rth)} = ${f(I,3)} mA, V_AK = ${f(vf)} V`:reg=='ZENER'?`I = (V_TH + V_Z)/R_TH = ${f(I,3)} mA (negative = reverse), V_AK = −${f(v.vz)} V`:`I = 0, V_AK = V_TH = ${f(Vd)} V`,'ON = a source of V_F. ZENER = a source of −V_Z. OFF = open circuit.'],['Check the guess',reg=='ON'?`I = ${f(I,3)} mA > 0 ✓`:reg=='ZENER'?'I < 0 and V_AK = −V_Z ✓':`V_AK = ${f(Vd)} V ≤ V_F${z?' and ≥ −V_Z':''} ✓`,'If it fails, change the guess and redo the previous step.'],['Load line (to draw it)',`Diode as a short: (V_AK = 0, I = ${f(v.vth/v.rth,2)} mA). As an open circuit: (V_AK = ${f(v.vth)} V, I = 0). Q is where it meets the diode curve.`,'Two points define a line.']],a:`Q = (V_AK = ${f(Vd,3)} V, I_D = ${f(I,3)} mA), diode ${reg}`}}},
led:{n:'LED series resistor',a:'“Calculate R to limit the current to …”, “design the LED circuit”',F:[['vs','Supply (V)',5],['vf','LED V_F (V)',2],['i','Desired current (mA)',20]],S:v=>{const R=(v.vs-v.vf)/v.i*1000,Rs=e12(R),Ia=(v.vs-v.vf)/Rs*1000;return{s:[['KVL around the loop',`Vs = V_R + V_F → V_R = ${f(v.vs)} − ${f(v.vf)} = ${f(v.vs-v.vf,2)} V`,'The resistor takes whatever the LED does not.'],['Ohm for R',`R = V_R/I = ${f(v.vs-v.vf,2)} V / ${f(v.i)} mA = ${f(R,1)} Ω`,'V/mA = kΩ.'],['Pick a standard value',`Next E12 value ≥ ${f(R,1)} Ω → ${f(Rs,1)} Ω, giving I = ${f(Ia,2)} mA`,'Round up so you never exceed the current.'],['Power in R',`P = V_R·I = ${f((v.vs-v.vf)*v.i,1)} mW`,'The resistor rating must be above this.']],a:`R ≈ ${f(R,1)} Ω (use ${f(Rs,1)} Ω)`}}},
mos:{n:'MOSFET operation point',a:'“Calculate the operation point of the MOSFET”, “draw the load line”, “power dissipated in the transistor”',F:[['g','V_GS (V)',7.5],['vdd','V_DD (V)',12],['rd','R_D (Ω)',40]],S:v=>{const s=v.g<2.5?0:(v.g-2.5)*40,[I,vds]=mosQ(v.g,v.vdd,v.rd),reg=!s?'cutoff':v.vdd-s*v.rd/1000>=2?'saturation':'ohmic',st=[['Is it ON at all?',`V_GS = ${f(v.g)} V vs threshold 2.5 V → ${s?'above: a channel exists':'below: CUTOFF'}`,'Below the threshold the MOSFET is an open switch: I_D = 0, V_DS = V_DD.']];if(s)st.push(['Current if it were a current source',`I_sat = (V_GS − 2.5)·40 = ${f(s)} mA`,'Course curves: each volt above the threshold adds 40 mA.'],['Try saturation',`V_DS = V_DD − I_sat·R_D = ${f(v.vdd)} − ${f(s*v.rd/1000,2)} = ${f(v.vdd-s*v.rd/1000,2)} V`,'Saturation needs V_DS ≥ 2 V (the knee).'],['Verdict: '+reg,reg=='saturation'?'V_DS ≥ 2 V → saturation, so I_D = I_sat.':`V_DS < 2 V → ohmic. R_on = 2 V/I_sat = ${f(2/s*1000,2)} Ω, I_D = V_DD/(R_D+R_on) = ${f(I,2)} mA`,'Ohmic = closed switch that acts like a small resistor.']);st.push(['Voltage and power',`V_DS = V_DD − I_D·R_D = ${f(vds,3)} V, P = V_DS·I_D = ${f(vds*I,2)} mW`,'A good switch has a small V_DS, so little heat.'],['Load line (to draw it)',`Short: I = V_DD/R_D = ${f(v.vdd/v.rd*1000,1)} mA. Open: V_DS = ${f(v.vdd)} V.`,'Q is where it meets the curve of your V_GS.']);return{s:st,a:`${reg} · I_D = ${f(I,2)} mA · V_DS = ${f(vds,3)} V`}}},
bjt:{n:'BJT operation point',a:'“Determine the operation point of the transistor”, “is it saturated?”, “calculate V_CE”',F:[['vbb','V_BB (V)',5],['rb','R_B (kΩ)',10],['vcc','V_CC (V)',15],['rc','R_C (kΩ)',1],['be','β',100]],S:v=>{const ib=Math.max((v.vbb-.7)/v.rb,0),ics=v.vcc/v.rc,ic=Math.min(v.be*ib,ics),reg=!ib?'cutoff':v.be*ib>=ics?'saturation':'active',vce=v.vcc-ic*v.rc;return{s:[['Base loop',`I_B = (V_BB − 0.7)/R_B = (${f(v.vbb)} − 0.7)/${f(v.rb)} = ${f(ib*1000,1)} µA`,ib?'If V_BB < 0.7 V nothing flows: cutoff.':'V_BB < 0.7 V: the base junction does not conduct → CUTOFF.'],['Current if active',`β·I_B = ${f(v.be)}·${f(ib,4)} mA = ${f(v.be*ib,2)} mA`,'In the active region I_C = β·I_B.'],['Maximum possible current',`I_C(sat) = V_CC/R_C = ${f(v.vcc)}/${f(v.rc)} = ${f(ics,2)} mA`,'The collector resistor limits it.'],['Compare',`${f(v.be*ib,2)} mA ${v.be*ib>=ics?'≥':'<'} ${f(ics,2)} mA → ${reg.toUpperCase()}`,'Larger: saturated (switch ON). Smaller: active (amplifier).'],['Collector loop',`I_C = ${f(ic,2)} mA, V_CE = V_CC − I_C·R_C = ${f(vce,2)} V`,'In saturation V_CE ≈ 0.'],['Power',`P = V_CE·I_C = ${f(vce*ic,2)} mW`,'']],a:`${reg} · I_C = ${f(ic,2)} mA · V_CE = ${f(vce,2)} V`}}},
rc:{n:'RC charging time',a:'“Time constant”, “time to reach X volts”, “voltage after t ms”',F:[['r','R (kΩ)',10],['c','C (µF)',10],['v','Source V (V)',10],['vt','Target voltage (V)',6.3]],S:v=>{const tau=v.r*v.c,k=v.vt>0&&v.vt<v.v,t=k?-tau*Math.log(1-v.vt/v.v):0;return{s:[['Time constant',`τ = R·C = ${f(v.r)} kΩ · ${f(v.c)} µF = ${f(tau)} ms`,'kΩ·µF = ms.'],['Charging law','v(t) = V·(1 − e^(−t/τ))','Starts at 0 and heads to V exponentially.'],['Time to the target',k?`t = −τ·ln(1 − ${f(v.vt)}/${f(v.v)}) = ${f(t,2)} ms`:'The target must be between 0 and V','Rearrange the law for t.'],['Rules of thumb',`1τ → 63% (${f(.632*v.v,2)} V). 5τ = ${f(5*tau)} ms → 99%`,'Handy for quick estimates.']],a:k?`t = ${f(t,2)} ms to reach ${f(v.vt)} V`:'Choose a target between 0 and V'}}}};
const ASK=[['“Find the operation point / Q point”','Thevenin around the nonlinear part → guess a region → solve → check it is consistent (or draw the load line).'],['“Calculate the current through …”','Reduce to one loop and use Ohm’s law. With several sources or nodes use KCL + KVL or Thevenin.'],['“Find the voltage across …”','Resistors in series with nothing else on the node → voltage divider. A load or several sources → Thevenin.'],['“Is it a source or a load?”','Current leaving the + terminal means source. Compute P = V·I with the passive sign: negative means it delivers.'],['“Power dissipated in the transistor”','Find Q first, then P = V_DS·I_D (MOSFET) or V_CE·I_C (BJT).'],['“Calculate R so that …”','Write KVL with the target current, solve for R, then round to a standard value.'],['“Draw the load line”','Two points: device short (I = V/R) and device open (V = source). Mark Q where the line meets the curve.'],['“Time to charge”, “voltage after t”','τ = R·C and v(t) = V(1 − e^(−t/τ)).'],['“Does it work as a switch?”','ON = saturation (BJT: β·I_B ≥ I_C(sat)) or ohmic with V_GS well above the threshold (MOSFET).']];
$('svq').innerHTML=ASK.map(a=>`<div class="fi"><b>${a[0]}</b><small>${a[1]}</small></div>`).join('');
function svForm(){const t=SOL[$('svt').value];$('svask').innerHTML='<b>You will see it as:</b> '+t.a;$('svf').innerHTML=t.F.map(([id,l,d])=>`<div class="sl"><label for="sv_${id}">${l}</label><input type="number" step="any" id="sv_${id}" value="${d}" style="padding:7px;border:1px solid var(--line);border-radius:6px;background:var(--card);color:var(--ink);font:inherit"></div>`).join('')}
function svSolve(){const t=SOL[$('svt').value],v={};for(const[id]of t.F){const e=$('sv_'+id);if(!e||e.value==='')return;v[id]=+e.value}if(v.r1<=0||v.r2<=0||v.r3<=0||v.rth<=0||v.rb<=0||v.rc<=0||v.rd<=0)return;const o=t.S(v);$('svs').innerHTML=o.s.map((s,i)=>`<div class="fi"><b>${i+1}. ${s[0]}</b><br><span class="f">${s[1]}</span><small>${s[2]||''}</small></div>`).join('')+`<div class="res"><b>Answer:</b> ${o.a}</div>`}
$('svt').innerHTML=Object.entries(SOL).map(([k,t])=>`<option value="${k}">${t.n}</option>`).join('');$('svt').onchange=()=>{svForm();draw()};svForm();
/* v4: op-amps (lesson V) + logic families (lesson IV) */
$('op1').innerHTML='<b>Configuration</b>'+sel('ot',['Inverting','Non-inverting','Voltage follower','Summing (Vin + V2)','Differential (V2 − Vin)','Comparator (Vin vs V2)','Schmitt trigger, inverting','Schmitt trigger, non-inverting'])+sl('oa','Vin peak',0,10,.5,2,'V')+sl('ov2','V2 (DC)',-10,10,.5,1,'V')+sl('o1','R1',.1,20,.1,1,'kΩ')+sl('o2','R2 = Rf',.1,50,.1,4,'kΩ')+sl('os','±Vsat (supply)',5,15,1,15,'V');
function op(){const k=$('ot').selectedIndex,A=V('oa'),v2=V('ov2'),r1=V('o1'),r2=V('o2'),vs=V('os'),B=r1/(r1+r2),T=k==6?B*vs:r1/r2*vs,a=[],b=[];let s=k==6?1:-1,sat=0;
for(let i=0;i<=200;i++){const t=i/100,x=A*Math.sin(6.2832*t);let y;
if(k==5)y=x>v2?vs:-vs;
else if(k>5){if(k==6){if(s>0&&x>T)s=-1;else if(s<0&&x<-T)s=1}else{if(s<0&&x>T)s=1;else if(s>0&&x<-T)s=-1}y=s*vs}
else{y=[-r2/r1*x,(1+r2/r1)*x,x,-r2/r1*(x+v2),r2/r1*(v2-x)][k];if(Math.abs(y)>vs){sat=1;y=Math.sign(y)*vs}}
a.push([t,x]);b.push([t,y])}
const ym=Math.max(vs,A,Math.abs(v2))*1.15,ln=[{p:[[0,vs],[2,vs]],c:'line',d:[4,4],w:1.5},{p:[[0,-vs],[2,-vs]],c:'line',d:[4,4],w:1.5},{p:a,c:'sig',w:2},{p:b,c:'out',w:3}];
if(k>5)ln.push({p:[[0,T],[2,T]],c:'ok',d:[2,3],w:1.5},{p:[[0,-T],[2,-T]],c:'ok',d:[2,3],w:1.5});if(k==5)ln.push({p:[[0,v2],[2,v2]],c:'ok',d:[2,3],w:1.5});
plot($('opc'),{x0:0,x1:2,y0:-ym,y1:ym,xl:'t (cycles)',yl:'V',ln});
const G=['A = −R2/R1 = '+f(-r2/r1),'A = 1 + R2/R1 = '+f(1+r2/r1),'A = 1 (v_out = v_in)','v_out = −R2·(Vin + V2)/R1','v_out = R2/R1·(V2 − Vin)  (needs R1=R3, R2=R4)','No feedback: v_out = +Vsat if V+ > V−, else −Vsat','UTP = B·Vsat = '+f(T)+' V, LTP = −'+f(T)+' V, B = R1/(R1+R2) = '+f(B,3),'UTP = R1/R2·Vsat = '+f(T)+' V, LTP = −'+f(T)+' V'][k],A0=k==0?r2/r1:k==1?1+r2/r1:1;
$('opres').innerHTML=`<div class="res">${G}${k<3?`<br>Max |Vin| without saturating = Vsat/|A| = ${f(vs/A0)} V`:''}<br>${k>4?tag('Switching: output is only +Vsat or −Vsat','blue'):sat?tag('SATURATED: output clipped','red'):tag('LINEAR','ok')}</div>`;
$('opsay').innerHTML='Blue = input, orange = output, dashed gray = ±Vsat. Ideal op-amp with negative feedback: v<sub>d</sub> = 0 (virtual short) and no input current. Real op-amps saturate 1–2 V below the rails. Schmitt: the two thresholds stop noise from flipping the output (green dotted).'}
const FAM={'74HC (CMOS, 5 V)':{h:4.9,l:.1,ih:3.15,il:1.35,oh:4,ol:4,jh:0,jl:0},'74LS (TTL)':{h:3.4,l:.25,ih:2,il:.8,oh:.4,ol:8,jh:.02,jl:.4}},FK=Object.keys(FAM),uw=x=>x>=1000?f(x/1000,3)+' mW':f(x,2)+' µW';
$('lg1c').innerHTML='<p>Driver (output)</p>'+sel('ld',FK)+'<p>Load (input)</p>'+sel('ll',FK);$('ll').selectedIndex=1;
$('lg2c').innerHTML=sl('lv','V DD',1,6,.1,5,'V')+sl('lf','Frequency',1,500,1,25,'MHz')+sl('lcp','C pd',1,50,1,20,'pF')+sl('lcl','C load per output',0,200,1,65,'pF')+sl('ln2','Outputs switching',1,8,1,1,'')+sl('lic','I CC static',0,100,1,0,'µA');
$('lg3c').innerHTML=sl('lph','t PHL',1,50,1,8,'ns')+sl('lpl','t PLH',1,50,1,10,'ns')+sl('lpn','Gates in series',1,12,1,5,'');
$('lg4c').innerHTML=sel('lgt',['Inverter: Y = NOT A','NAND: Y = NOT(A·B)','NOR: Y = NOT(A+B)','Complex: Y = NOT[A·(B+C·D)]'])+'<p>'+['A','B','C','D'].map((x,i)=>`<label style="margin-right:14px"><input type="checkbox" id="lc${i}"> ${x} = 1</label>`).join('')+'</p>';
function lg(){const d=FAM[FK[$('ld').selectedIndex]],l=FAM[FK[$('ll').selectedIndex]],nmh=d.h-l.ih,nml=l.il-d.l,ok=nmh>=0&&nml>=0;let fo;
if(!l.jh)fo='CMOS inputs draw almost no DC current: the limit is speed (input capacitance). Practical limit ≈ 50 loads.';else{const a=d.oh/l.jh,b=d.ol/l.jl;fo=`Fan-out HIGH = I<sub>OH</sub>/I<sub>IH</sub> = ${f(d.oh)} mA / ${f(l.jh*1000)} µA = ${f(a,1)}<br>Fan-out LOW = I<sub>OL</sub>/I<sub>IL</sub> = ${f(d.ol)} mA / ${f(l.jl)} mA = ${f(b,1)}<br><b>Fan-out = ${Math.floor(Math.min(a,b))}</b> (the smaller)`}
$('lg1r').innerHTML=`<div class="res">NM<sub>H</sub> = V<sub>OH</sub> − V<sub>IH</sub> = ${f(d.h)} − ${f(l.ih)} = ${f(nmh)} V<br>NM<sub>L</sub> = V<sub>IL</sub> − V<sub>OL</sub> = ${f(l.il)} − ${f(d.l)} = ${f(nml)} V<br>${tag(ok?'Voltage compatible':'NOT compatible',ok?'ok':'red')}</div><div class="res">${fo}</div><div class="say">Driver’s V<sub>OH</sub>(min) must be ≥ load’s V<sub>IH</sub>(min), and driver’s V<sub>OL</sub>(max) ≤ load’s V<sub>IL</sub>(max). Both margins must be positive.</div>`;
const v=V('lv'),fq=V('lf'),n=V('ln2'),pt=V('lcp')*v*v*fq*n,pl=V('lcl')*v*v*fq*n,ps=v*V('lic');
$('lg2r').innerHTML=`<div class="res">P<sub>static</sub> = V·I<sub>CC</sub> = ${uw(ps)}<br>P<sub>T</sub> = C<sub>pd</sub>·V²·f·N = ${uw(pt)}<br>P<sub>L</sub> = C<sub>L</sub>·V²·f·N = ${uw(pl)}<br><b>P<sub>total</sub> = ${uw(ps+pt+pl)}</b></div><div class="say">Dynamic power grows with V² and with f: halve V<sub>DD</sub> and you cut it to a quarter. pF·V²·MHz = µW.</div>`;
const ph=V('lph'),pL=V('lpl'),N=V('lpn'),w=N*Math.max(ph,pL),alt=Math.ceil(N/2)*pL+Math.floor(N/2)*ph;
$('lg3r').innerHTML=`<div class="res">Worst case = N·max(t<sub>PHL</sub>,t<sub>PLH</sub>) = ${N}·${f(Math.max(ph,pL))} = ${f(w)} ns<br>f<sub>max</sub> ≈ 1/delay = ${f(1000/w,1)} MHz<br>Alternating edges (inverting chain) = ${f(alt)} ns</div>`;
const gt=$('lgt').selectedIndex,[A,B,C,D]=[0,1,2,3].map(i=>$('lc'+i).checked),pd=[A,A&&B,A||B,A&&(B||(C&&D))][gt];
$('lg4r').innerHTML=`<div class="res">${['PDN (nMOS): A','PDN: A in series with B (AND)','PDN: A in parallel with B (OR)','PDN: A in series with [B in parallel with (C in series with D)]'][gt]}<br>PUN (pMOS) is the dual: series ↔ parallel.<br>PDN ${tag(pd?'conducts':'open',pd?'ok':'blue')} PUN ${tag(pd?'open':'conducts',pd?'blue':'ok')} → <b>Y = ${pd?0:1}</b></div><div class="say">nMOS ON with a 1, pMOS ON with a 0. Exactly one network conducts, so no DC path from V<sub>DD</sub> to ground: that is why CMOS static power is so small. Never leave a CMOS input unconnected.</div>`}
$('learn').insertAdjacentHTML('beforeend','<details><summary>9. Op-amps: the ideal amplifier</summary><p>An op-amp amplifies the <b>difference</b> v<sub>d</sub> = v<sub>+</sub> − v<sub>−</sub> with a huge gain: <span class="f">v<sub>o</sub> = A<sub>o</sub>·v<sub>d</sub></span>. Ideal: infinite gain, infinite input impedance (no input current), zero output impedance. With <b>negative feedback</b> (output wired to the − input) the op-amp stays linear and forces <b>v<sub>+</sub> = v<sub>−</sub></b> (virtual short). Inverting: <span class="f">−R2/R1</span>. Non-inverting: <span class="f">1 + R2/R1</span>. Follower: gain 1, a buffer. Without feedback it is a comparator: output = ±V<sub>sat</sub>. Try the “Op-amps” tab.</p></details><details><summary>10. Logic families: CMOS and TTL</summary><p><b>CMOS</b> gate = pull-up network (pMOS) + pull-down network (nMOS), dual to each other. A level counts as 1 or 0 only beyond V<sub>IH</sub> / V<sub>IL</sub>; <b>noise margins</b>: <span class="f">NM<sub>H</sub> = V<sub>OH</sub> − V<sub>IH</sub></span>, <span class="f">NM<sub>L</sub> = V<sub>IL</sub> − V<sub>OL</sub></span>. <b>Fan-out</b> = how many inputs one output drives (TTL: from currents; CMOS: limited by capacitance). CMOS power: tiny static, but dynamic <span class="f">P = C·V<sub>DD</sub>²·f</span>. Outputs: totem-pole, open-drain/collector (needs a pull-up) and tri-state. Try the “Logic” tab.</p></details>');
F.push(['Op-amps','Ideal op-amp rules','v₊ = v₋ (virtual short) · i₊ = i₋ = 0','Valid only with negative feedback (op-amp linear, not saturated).'],['Op-amps','Open-loop','v_o = A_o·(v₊ − v₋)','Without feedback the output saturates to +V_CC or −V_EE.'],['Op-amps','Inverting amplifier','v_out = −(R_f/R1)·v_in','Output inverted 180°. Input resistance = R1.'],['Op-amps','Non-inverting amplifier','v_out = (1 + R_f/R1)·v_in','In phase. Gain is always ≥ 1.'],['Op-amps','Voltage follower','v_out = v_in','Buffer: infinite-ish input, low output impedance.'],['Op-amps','Summing amplifier','v_out = −R_f·(v1/R1 + v2/R2)','Each input has its own weight (its series resistor).'],['Op-amps','Differential amplifier','v_o = (R2/R1)·(v2 − v1)  if R1=R3, R2=R4','Subtracts two voltages.'],['Op-amps','Integrator','v_out = v_out0 − 1/(R·C) ∫ v_in dt','Drifts to saturation; add a resistor in parallel with C (a pole).'],['Op-amps','Schmitt trigger (inverting)','B = R1/(R1+R2) · UTP = B·V_sat · LTP = −B·V_sat · H = 2B·V_sat','Positive feedback gives two thresholds (hysteresis) against noise.'],['Op-amps','Schmitt trigger (non-inverting)','UTP = (R1/R2)·V_sat · LTP = −(R1/R2)·V_sat','Output follows the input once UTP is crossed.'],['Op-amps','Max input before saturation','|v_in| ≤ V_sat/|A|','Check this in every exercise. V_sat ≈ supply rail.'],['Op-amps','Max output current','R_load ≥ V_out / (I_max − I_feedback)','Remember the feedback network also loads the output.'],['Op-amps','A/D resolution','Δ = V_FS/(2^N − 1) · bits used = log2(range/Δ)','Adapt the signal to 0–V_FS to use all the bits.'],['Logic','Noise margins','NM_H = V_OH − V_IH · NM_L = V_IL − V_OL','Driver’s V_OH, V_OL against load’s V_IH, V_IL. Both must be > 0 for compatibility.'],['Logic','CMOS networks','PDN (nMOS): series = AND, parallel = OR · PUN (pMOS) = dual','nMOS ON with 1, pMOS ON with 0. Get Y with De Morgan.'],['Logic','Fan-out (TTL)','FO = min(I_OH/I_IH , I_OL/I_IL)','Use absolute values of currents. Smaller one wins.'],['Logic','Fan-out (CMOS)','Limited by capacitance, ≈ 50 loads','More loads = more C = lower max frequency.'],['Logic','Static power','P_S = V_CC·I_CC','TTL: constant. CMOS: only leakage (µA).'],['Logic','Energy per cycle (CMOS)','E = C·V_DD² (half stored, half heat)','Per charge/discharge cycle.'],['Logic','Dynamic power (CMOS)','P = C·V_DD²·f · P_T = C_pd·V_DD²·f·N_sw · P_L = ΣC_L·V_DD²·f·N_sw','P_D = P_T + P_L. Depends on frequency and V².'],['Logic','Propagation delay','t_PHL, t_PLH at 50% points · path delay = Σ gate delays','Use the worst (largest) for a safe f_max ≈ 1/delay.'],['Logic','Transition times','t_THL, t_TLH measured between 10% and 90%','Not the same as propagation delay.'],['Logic','Output types','Totem-pole · Open-drain/collector (pull-up, wired-AND) · Tri-state (high-Z)','Never wire totem-pole outputs together. Never leave CMOS inputs open.']);
$('fc').innerHTML='<option value="">All topics</option>'+[...new Set(F.map(r=>r[0]))].map(c=>`<option>${c}</option>`).join('');
EX.push(['Op-amps','Current sensor 4–20 mA (non-inverting)','Sensor current I_E = 4–20 mA enters the node between two 100 Ω resistors (one to +15 V, one to ground), which feeds the + input. R1 (to ground) and R2 (feedback) set the gain; supply ±15 V. (1) U_s as a function of I_E, R1, R2. (2) R1 = 1 kΩ: max R2 without saturating. (3) Max output current 50 mA: min load R.','(1) Thevenin at +: V_TH = 15/2 = 7.5 V, R_TH = 50 Ω, so V+ = 7.5 + 50·I_E. Non-inverting: <b>U_s = (1 + R2/R1)·(7.5 + 50·I_E)</b>. (2) Worst case I_E = 20 mA: V+ = 8.5 V. Need (1+R2/R1)·8.5 ≤ 15 → R2/R1 ≤ 0.765 → <b>R2 ≈ 765 Ω</b>. (3) At 15 V the feedback branch takes 15/(1k+0.765k) = 8.5 mA, so the load gets ≤ 41.5 mA → <b>R ≥ 15/41.5 mA ≈ 361 Ω</b>. (Assumes V_sat = ±15 V and I_E flowing into the node.)']);
EX.push(['Op-amps','Current-voltage converter, 4–20 mA → 0–5 V','Stage 1: inverting, current I_E into the − input, 500 Ω feedback, output V_P. Stage 2: 2 kΩ in series with the − input, R_A feedback, V_A on the + input. (1) V_P vs I_E. (2) V_S vs V_P. (3) V_A and R_A so that V_S = (I_E − 4 mA)·5/16 mA.','(1) All of I_E goes through 500 Ω: <b>V_P = −500·I_E</b> (−2 V to −10 V). (2) Stage 2 is a summing/non-inverting mix: <b>V_S = V_A·(1 + R_A/2k) − V_P·R_A/2k</b>. (3) Target V_S = 312.5·I_E − 1.25. Slope: 500·R_A/2k = 312.5 → <b>R_A = 1.25 kΩ</b>. Offset: V_A·1.625 = −1.25 → <b>V_A ≈ −0.77 V</b>.']);
EX.push(['Op-amps','Two-input inverting circuit (u_E1, u_E2)','R2 = 10 kΩ from u_E1 and R3 = 5 kΩ from u_E2 both go to the − input; R1 = 5 kΩ is the feedback; + input through R4 = 10 kΩ to ground; ±15 V. u_E2 = 8 V DC. (1) u_S vs inputs. (2) Plot u_S if u_E1 = 8 V<sub>pp</sub> sine, T = 1 ms. (3) What if u_E2 = 12 V? Max u_E2 without distortion?','(1) Summing amplifier, R4 carries no current: <b>u_S = −R1·(u_E1/R2 + u_E2/R3) = −0.5·u_E1 − u_E2</b>. (2) u_E1 has 4 V peak → −0.5·u_E1 is a 2 V peak inverted sine (T = 1 ms) around −8 V: u_S swings between −10 V and −6 V. (3) At 12 V: −12 ± 2 → −14 V to −10 V, still inside ±15 V, no distortion. Limit: u_E2 + 2 ≤ 15 → <b>u_E2 ≤ 13 V</b>.']);
EX.push(['Op-amps','Max input swing of a differential stage','v_in drives R1 = 1k to the − input and R2 = 4k to the + input; R4 = 1k from + to ground; R3 = 4k feedback; ±15 V. Maximum excursion of v_in without saturating?','V+ = v_in·R4/(R2+R4) = v_in/5. v_out = (1 + R3/R1)·V+ − (R3/R1)·v_in = 5·v_in/5 − 4·v_in = <b>−3·v_in</b>. |v_out| ≤ 15 V → <b>|v_in| ≤ 5 V</b> (−5 V to +5 V).']);
EX.push(['Op-amps','Temperature sensor adaptation','Sensor −25 °C = −2.5 V, +75 °C = 7.5 V. A microcontroller reads 0–5 V. Which op-amp circuit?','Slope 5 V/10 V = 0.5, offset: −2.5 V → 0 V. Use a <b>differential/summing stage</b>: V_out = 0.5·(V_sensor + 2.5) = 0.5·V_sensor + 1.25. E.g. an inverting summer (gain −0.5) fed by the sensor and a −2.5 V reference, followed by an inverter; or a non-inverting stage with a divider reference. Check: −2.5 → 0 V and 7.5 → 5 V.']);
EX.push(['Op-amps','Lost A/D bits','Sensor 2–3 V into a 10-bit A/D with range 0–5 V. How many bits are really used?','Resolution = 5/(2<sup>10</sup>−1) = 4.89 mV. Steps = 1 V/4.89 mV ≈ 204. Bits = log<sub>2</sub>(204) = <b>7.67</b>: we lose more than 2 bits. Amplify and shift the signal to 0–5 V with an op-amp.']);
EX.push(['Logic families','CMOS ↔ TTL compatibility and fan-out','74HC04 (V_OH 4.9, V_OL 0.1, I_OH/I_OL 4 mA) drives 74LS08 inputs (V_IH 2.0, V_IL 0.8, I_IH 20 µA, I_IL 0.4 mA). (a) Compatible? And LS → HC (V_OH 3.4, V_OL 0.25; HC V_IH 3.15, V_IL 1.35)? (b) Fan-out?','(a) HC→LS: NM_H = 4.9 − 2.0 = 2.9 V, NM_L = 0.8 − 0.1 = 0.7 V → compatible. LS→HC: NM_H = 3.4 − 3.15 = 0.25 V, NM_L = 1.35 − 0.25 = 1.1 V → also compatible at 5 V, but the high margin is thin. (b) HIGH: 4 mA/20 µA = 200. LOW: 4 mA/0.4 mA = 10. <b>Fan-out = 10</b>.']);
EX.push(['Logic families','Fan-out of a 7400 NAND','I_IH = 40 µA, I_OH = −400 µA, I_IL = −1.6 mA, I_OL = 16 mA. Fan-out?','HIGH: 400 µA/40 µA = 10. LOW: 16 mA/1.6 mA = 10. <b>Fan-out = 10</b> in both states. (The slide prints mA for the HIGH currents; they are µA.)']);
EX.push(['Logic families','Dynamic power of a chip','0.25 µm CMOS, 500 MHz, 15 fF per gate, 2.5 V. Power per gate and for 10⁶ gates switching every clock?','P = C·V²·f = 15·10⁻¹⁵·2.5²·500·10⁶ = 46.9 µW per gate. For 10⁶ gates: <b>46.9 W</b>, unrealistic because not all gates switch at once at full frequency.']);
EX.push(['Logic families','Inverter driving five inverters (74HC04)','V_DD 5 V, C_pd = 20 pF, C_in = 10 pF each, stray 15 pF, f = 25 MHz. (1) Load capacitance of the first inverter. (2) Its power.','(1) C_Load = 5·10 + 15 = <b>65 pF</b>. (2) P = C_pd·V²·f + C_Load·V²·f = 12.5 mW + 40.625 mW = <b>53.125 mW</b>.']);
EX.push(['Logic families','74HC00: power and delay','V_CC 5 V, I_CC = 2 µA, C_pd = 20 pF, C_L = 15 pF, t_PHL = 8 ns, t_PLH = 10 ns, f = 10 MHz (output toggles each cycle). Static, dynamic and total power; delay of 5 NANDs in series.','P_static = 5·2 µA = 10 µW. P_dyn = (20 + 15) pF·25·10 MHz = 8.75 mW. <b>P_total ≈ 8.76 mW</b>. Worst-case delay = 5·10 ns = <b>50 ns</b> (f_max ≈ 20 MHz).']);
$('exf').innerHTML='<option value="">All topics</option>'+[...new Set(EX.map(c=>c[0]))].map(c=>`<option>${c}</option>`).join('');exr();
Object.assign(GEN,{opinv:()=>{const a=pk([1,2,4.7,10]),b=pk([10,22,47,100]),v=pk([.1,.2,.5,1]);return{q:`Inverting amplifier: R1 = ${a} kΩ, Rf = ${b} kΩ, v_in = ${v} V. v_out in V (ideal, no saturation)?`,a:-b/a*v,s:`v_out = −Rf/R1·v_in = −${b}/${a}·${v} = ${f(-b/a*v,3)} V`}},opnon:()=>{const a=pk([1,2,4.7,10]),b=pk([10,22,47]),v=pk([.1,.2,.5]);return{q:`Non-inverting amplifier: R1 = ${a} kΩ, Rf = ${b} kΩ, v_in = ${v} V. v_out in V?`,a:(1+b/a)*v,s:`v_out = (1 + Rf/R1)·v_in = (1 + ${b}/${a})·${v} = ${f((1+b/a)*v,3)} V`}},opsat:()=>{const g=pk([2,4,5,10]),vs=pk([12,15]);return{q:`An op-amp with ±${vs} V supply amplifies with |gain| = ${g}. Maximum input amplitude (V) before saturating?`,a:vs/g,s:`|v_in| ≤ Vsat/|A| = ${vs}/${g} = ${f(vs/g,3)} V`}},nm:()=>{const vo=pk([3.4,4.4,4.9]),vi=pk([2,2.4,3.15]);return{q:`Driver V_OH(min) = ${vo} V, load V_IH(min) = ${vi} V. High-level noise margin NM_H in V?`,a:vo-vi,s:`NM_H = V_OH − V_IH = ${vo} − ${vi} = ${f(vo-vi,3)} V`}},fo:()=>{const o=pk([4,8,16]),i=pk([.4,1.6,.8]);return{q:`Driver sinks up to ${o} mA in the LOW state; each load input needs ${i} mA. Fan-out (LOW state)?`,a:Math.floor(o/i),s:`FO = I_OL/I_IL = ${o}/${i} = ${f(o/i,2)} → ${Math.floor(o/i)}`}},cpw:()=>{const c=pk([10,15,20,50]),v=pk([1.8,3.3,5]),fr=pk([10,25,100]);return{q:`CMOS dynamic power: C = ${c} pF, V_DD = ${v} V, f = ${fr} MHz. P in µW?`,a:c*v*v*fr,s:`P = C·V²·f = ${c} pF·${v}²·${fr} MHz = ${f(c*v*v*fr,2)} µW`}},dly:()=>{const a=pk([6,8,12]),b=pk([9,10,15]),n=pk([3,4,5,8]);return{q:`${n} gates in series, t_PHL = ${a} ns, t_PLH = ${b} ns. Worst-case total delay in ns?`,a:n*Math.max(a,b),s:`${n}·max(${a},${b}) = ${n*Math.max(a,b)} ns`}}});
Object.assign(TOP,{opinv:'Op-amp: inverting',opnon:'Op-amp: non-inverting',opsat:'Op-amp: saturation limit',nm:'Logic: noise margin',fo:'Logic: fan-out',cpw:'CMOS dynamic power',dly:'Logic: path delay'});
$('ptop').innerHTML='<option value="any">Any topic</option>'+Object.entries(TOP).map(([k,v])=>`<option value="${k}">${v}</option>`).join('');
Object.assign(SOL,{opamp:{n:'Op-amp amplifier',a:'“Find v_out”, “gain of the circuit”, “will it saturate?”',F:[['kind','Circuit: 0 inverting, 1 non-inverting',0],['r1','R1 (kΩ)',1],['rf','Rf (kΩ)',4],['vin','v_in (V)',2],['vs','±Vsat (V)',15]],S:v=>{const inv=v.kind==0,A=inv?-v.rf/v.r1:1+v.rf/v.r1,vo=A*v.vin,sat=Math.abs(vo)>v.vs;return{s:[['Negative feedback → ideal rules','v₊ = v₋ and i₊ = i₋ = 0','The op-amp is linear, so the virtual short applies.'],['Write the node equation',inv?'v_in/R1 = −v_out/Rf (current through R1 = current through Rf)':'v₋ = v_out·R1/(R1+Rf) = v_in','Inverting: current balance at the − node. Non-inverting: divider on the feedback.'],['Gain',inv?`A = −Rf/R1 = −${f(v.rf)}/${f(v.r1)} = ${f(A,3)}`:`A = 1 + Rf/R1 = 1 + ${f(v.rf)}/${f(v.r1)} = ${f(A,3)}`,'Only resistor ratios matter.'],['Output',`v_out = A·v_in = ${f(A,3)}·${f(v.vin)} = ${f(vo,3)} V`,'Then compare with the supply.'],['Saturation check',sat?`|${f(vo,2)}| > ${f(v.vs)} V → it saturates: v_out ≈ ${f(Math.sign(vo)*v.vs)} V`:`|${f(vo,2)}| ≤ ${f(v.vs)} V → linear. Max |v_in| = ${f(v.vs/Math.abs(A),3)} V`,'Always check this last.']],a:sat?`Saturated: v_out ≈ ${f(Math.sign(vo)*v.vs)} V (linear would be ${f(vo,2)} V)`:`v_out = ${f(vo,3)} V, gain ${f(A,3)}`}}},cpow:{n:'CMOS power',a:'“Power consumed by the gate”, “dynamic power”, “total power”',F:[['vdd','V_DD (V)',5],['fq','f (MHz)',10],['cpd','C_pd (pF)',20],['cl','C_L (pF)',15],['icc','I_CC static (µA)',2]],S:v=>{const ps=v.vdd*v.icc,pt=v.cpd*v.vdd**2*v.fq,pl=v.cl*v.vdd**2*v.fq;return{s:[['Static power',`P_S = V·I_CC = ${f(v.vdd)}·${f(v.icc)} µA = ${f(ps,2)} µW`,'Leakage only in CMOS.'],['Internal (transient) power',`P_T = C_pd·V²·f = ${f(pt,1)} µW`,'pF·V²·MHz = µW.'],['Load power',`P_L = C_L·V²·f = ${f(pl,1)} µW`,'Charging the external capacitance.'],['Total',`P = P_S + P_T + P_L = ${f((ps+pt+pl)/1000,4)} mW`,'Dynamic usually dominates at high f.']],a:`P_total = ${f((ps+pt+pl)/1000,4)} mW`}}},fanout:{n:'Logic fan-out',a:'“How many inputs can one output drive?”',F:[['ioh','Driver I_OH (mA)',4],['iol','Driver I_OL (mA)',4],['iih','Load I_IH (mA)',.02],['iil','Load I_IL (mA)',.4]],S:v=>{const a=v.ioh/v.iih,b=v.iol/v.iil;return{s:[['HIGH state',`I_OH/I_IH = ${f(v.ioh)}/${f(v.iih,3)} = ${f(a,1)}`,'Driver sources current to the loads.'],['LOW state',`I_OL/I_IL = ${f(v.iol)}/${f(v.iil,3)} = ${f(b,1)}`,'Driver sinks current from the loads.'],['Choose the smaller',`Fan-out = ${Math.floor(Math.min(a,b))}`,'Both states must work.']],a:`Fan-out = ${Math.floor(Math.min(a,b))}`}}}});
$('svt').innerHTML=Object.entries(SOL).map(([k,t])=>`<option value="${k}">${t.n}</option>`).join('');svForm();

