TRI='<path d="M130,40V110L205,75Z" fill="var(--card)" stroke="currentColor" stroke-width="2.4"/>'+T(138,58,'−','start')+T(138,99,'+','start')+w('M205,75H275')+T(272,66,'Vout','end')+D(275,75),
