quiz('op',[['Inverting amplifier, R1 = 1 kΩ, R2 = 10 kΩ, Vin = 0.5 V, supply ±15 V. Vout?',['+5 V','−5 V','−10 V','−15 V (saturated)'],1,'A = −R2/R1 = −10, so −10·0.5 = −5 V, inside ±15 V.'],['With negative feedback an ideal op-amp forces…',['V+ = V−','Vout = 0','R1 = R2','a huge input current'],0,'The virtual short: V+ = V− (and no current enters the inputs).'],['Which circuit is in phase with gain 1 + R2/R1?',['Inverting','Non-inverting','Summing','Comparator'],1,'The signal enters the + input, so there is no inversion.'],['No feedback and V+ > V−. The output is…',['+Vsat','0 V','V+ − V−','infinite'],0,'Huge gain pushes the output to the positive rail: a comparator.'],['Why does a Schmitt trigger have two thresholds?',['To amplify more','Positive feedback moves the threshold with the output','To save power','It has no feedback'],1,'The output state shifts the threshold, so noise inside the gap cannot flip it.']]);
quiz('lg',[['Noise margin high NMH =',['V_OH − V_IH','V_IH − V_OH','V_IL − V_OL','V_OL − V_IL'],0,'Driver’s guaranteed HIGH output minus the load’s minimum accepted HIGH.'],['Two nMOS in series in the pull-down network (and two pMOS in parallel above) make…',['NAND','NOR','NOT','XOR'],0,'Series nMOS = AND in the PDN; the output is the complement: NAND.'],['Halving V_DD changes CMOS dynamic power (P = C·V²·f) by…',['÷2','÷4','÷8','nothing'],1,'Power goes with V²: (1/2)² = 1/4.'],['Driver: I_OH = 0.4 mA, I_OL = 8 mA. Load: I_IH = 20 µA, I_IL = 0.4 mA. Fan-out?',['10','20','400','2'],1,'HIGH: 400 µA/20 µA = 20. LOW: 8/0.4 = 20. Smaller one → 20.'],['A floating CMOS input is dangerous because…',['it is slow','it can float between V_IL and V_IH and turn both transistors on','it has no capacitance','it makes a latch'],1,'Both nMOS and pMOS conduct: shoot-through current, heat and erratic outputs.']]);
