const chp=(cx,y,l,t)=>`<rect x="${cx-10}" y="${y}" width="20" height="22" rx="4" fill="${t=='p'?'#e8590c':'#2f7de1'}"/><text x="${cx}" y="${y+15}" font-size="11" font-weight="700" fill="#fff" text-anchor="middle">${l}</text>`,GS={NOT:[['inv','A']],NAND:[['nand','A','B']],NOR:[['nor','A','B']],AND:[['nand','A','B'],['inv','X']],OR:[['nor','A','B'],['inv','X']]},GH={NOT:'1 pMOS on top + 1 nMOS below.',NAND:'nMOS in <b>series</b>, pMOS in <b>parallel</b>.',NOR:'nMOS in <b>parallel</b>, pMOS in <b>series</b>.',AND:'A NAND stage + an inverter: the inverter flips NAND into AND.',OR:'A NOR stage + an inverter: the inverter flips NOR into OR.'},gev=(k,a,b)=>+({NOT:!a,AND:a&&b,OR:a||b,NAND:!(a&&b),NOR:!(a||b)}[k]);
