document.querySelector('main').insertAdjacentHTML('beforeend',`<section id="rf"><h2>More 📚</h2><p class="lead">Everything else from the lessons, short and visual.</p>
<div class="box"><b>🔬 Op-amp lab 2: integrator and rectifiers</b>${sel('xt',['Integrator (ideal)','Integrator (stable, with R2)','Passive diode rectifier (0.7 V)','Active half-wave rectifier','Precision rectifier (improved)'])}${sl('xa','Vin peak',.1,5,.1,1,'V')}${sl('xf','Frequency',10,1000,10,100,'Hz')}${sl('xr','R1',1,100,1,10,'kΩ')}${sl('xc','C',.01,10,.01,1,'µF')}${sl('xr2','R2 (stable integrator / rectifier)',1,500,1,100,'kΩ')}<canvas id="xcv"></canvas><div id="xres"></div></div>
<div class="box"><b>📈 Inverter VTC: where is 0 and 1?</b>${sl('xv','V DD',1.8,5,.1,5,'V')}<canvas id="vtc"></canvas><div id="vres"></div></div>
<div class="box"><b>📊 dB → V/V (datasheet gains)</b>${sl('xd','Gain',20,140,1,123,'dB')}<div id="xdb" class="res"></div><div class="say">OP27 123 dB · TL071 126 dB · 741 106 dB. Z<sub>i</sub>: 2 GΩ · 1 TΩ · 300 kΩ. Huge but not infinite.</div></div>
<div class="box"><b>🧱 Inside an op-amp (741)</b>${SV(70,BX(5,15,80,40,'Input stage')+ARW(87,35)+BX(112,15,80,40,'Gain stage')+ARW(194,35)+BX(219,15,76,40,'Output stage'))}<div class="say">High input resistance → huge gain → low output resistance. Input is differential, output is referred to ground.</div></div>
<div class="box"><b>🔁 Why op-amps? The control loop</b>${SV(120,BX(2,15,62,34,'Regulator')+ARW(62,32)+BX(84,15,58,34,'Actuator')+ARW(142,32)+BX(165,15,55,34,'Process')+ARW(222,32)+T(270,36,'Output','middle')+w('M192,49V90H100')+BX(45,75,55,30,'Sensor')+w('M45,90H18V32H5')+T(150,104,'amplifier + filter'))}<div class="say">The sensor signal is tiny and noisy: an <b>amplifier</b> boosts it and a <b>filter</b> cleans it. Building that from BJTs/MOSFETs is hard → use an op-amp.</div></div>
${DT('✅ Op-amp: ideal vs real','<div class="res">Input R: ∞ → 10⁵–10⁸ Ω<br>Output R: 0 → 20–100 Ω<br>Max output current: 20–100 mA<br>Gain A<sub>d</sub>: ∞ → 20 000–500 000<br>Bandwidth: gain drops above a corner (e.g. 80 dB flat to 100 Hz)<br>DC error: output offset V<sub>S</sub> ≠ 0 (use offset-null pins)<br>Inputs and output limited by the supply. <b>Rail-to-rail</b> parts get closer to the rails.</div>')}
${DT('📝 Analysis recipe','<p class="kid" style="font-size:16px">1️⃣ Is there negative feedback? 2️⃣ Then v₊ = v₋. 3️⃣ No current into the inputs. 4️⃣ Write KCL at the − node. 5️⃣ Check saturation (±Vsat).</p>')}
${DT('⚖️ Comparator, Schmitt with reference, LM393','<p class="kid" style="font-size:16px">No feedback → output = ±Vsat. Noisy input → output chatters. <b>Schmitt</b> adds positive feedback: two thresholds (V<sub>Lt</sub>, V<sub>Ht</sub>). A <b>reference voltage</b> shifts the centre V<sub>st</sub> left or right. <b>LM393</b>: 2–36 V supply, offset ±3 mV, <b>open-collector</b> output → needs a pull-up resistor.</p>')}
${DT('🎛️ Active filter and regulator','<p class="kid" style="font-size:16px">First-order RC filters are easy but gentle. Better filters need L, which is big and noisy, so we use op-amps: the <b>Sallen-Key low-pass</b> = 1 op-amp (gain 1) + 2 R + 2 C. <b>Linear regulator</b>: op-amp + Zener + transistor gives 12 V; in practice use LM7805/7812/7815. Simple but low efficiency: phone chargers use <b>switching</b> supplies.</p>')}
${DT('🕰️ Chips: history','<p class="kid" style="font-size:16px">1958 Kilby (germanium IC) · 1959 Noyce (silicon, monolithic) · 1971 <b>Intel 4004</b>: 2300 transistors, 4 bits, 740 kHz, 10 µm · 2022 3 nm (Samsung GAAFET, TSMC FinFET) · 2024-25 2 nm. FinFET = MOSFET with a vertical fin: less leakage, better heat. Moore’s law is slowing.</p>')}
${DT('🏭 Families: CMOS, TTL, ECL, BiCMOS','<p class="kid" style="font-size:16px"><b>CMOS</b> = nMOS + pMOS, tiny static power. <b>TTL</b> (bipolar): old, more complex, V<sub>CC</sub> = 5 V only, constant power, hurt by VLSI; low-power (LS) and fast versions exist. <b>ECL</b>: very fast, rare. <b>BiCMOS</b>: bipolar + CMOS.</p>')}
${DT('🔌 Switch model and De Morgan','<p class="kid" style="font-size:16px">nMOS = switch closed with 1; pMOS = closed with 0. PDN: series = AND, parallel = OR; PUN is the dual. Example Y = A·(B+C·D): PDN builds Ȳ; for the PUN use De Morgan: Y = Ā + B̄·(C̄+D̄). Where PDN has series, PUN has parallel.</p>')}
${DT('⏱️ Timing and loading','<p class="kid" style="font-size:16px">t<sub>PHL</sub>/t<sub>PLH</sub> are measured at the <b>50%</b> points. Transition times t<sub>THL</sub>/t<sub>TLH</sub> (and input t<sub>r</sub>/t<sub>f</sub>) use <b>10%–90%</b>. <b>CMOS loads are capacitive</b>: more inputs = more C = slower; limit ≈ 50. <b>TTL loads are current</b>: driver sources I<sub>IH</sub> and sinks I<sub>IL</sub> from each load.</p>')}
${DT('⚡ Where CMOS power comes from','<p class="kid" style="font-size:16px">Charging C from V<sub>DD</sub> takes E = C·V<sub>DD</sub>²: <b>half</b> is stored (½CV²), <b>half</b> is heat in the pMOS. Discharging dumps the stored half in the nMOS. Per cycle: C·V<sub>DD</sub>² → P = f·C·V<sub>DD</sub>². Extra: <b>through current</b> when both transistors conduct briefly while switching (slow input edges make it worse). TTL power is constant with frequency; CMOS grows with f.</p>')}
${DT('🔘 Output types','<p class="kid" style="font-size:16px"><b>Totem-pole</b>: actively drives both 1 and 0, fast. Never join two outputs. <b>Open-drain / open-collector</b>: only pulls to 0; needs an external <b>pull-up</b>; outputs can be joined (wired-AND). <b>Tri-state</b>: 1, 0 or <b>high-Z</b> (disconnected) via an enable. Never leave CMOS inputs open.</p>')}</section>`);
function xop(){const k=$('xt').selectedIndex,A=V('xa'),fq=V('xf'),R=V('xr'),C=V('xc'),R2=V('xr2'),vs=15,T0=1000/fq,rc=R*C,a=[],b=[];let am='';
for(let i=0;i<=200;i++){const u=i/100,t=u*T0,x=A*Math.sin(6.2832*u),wm=6.2832/T0;let y;
if(k==0)y=-A/(wm*rc)*(1-Math.cos(6.2832*u));else if(k==1){const wr=wm*R2*C;y=-(R2/R)*A/Math.sqrt(1+wr*wr)*Math.sin(6.2832*u-Math.atan(wr))}
else if(k==2)y=Math.max(x-.7,0);else if(k==3)y=Math.max(x,0);else y=x>0?-R2/R*x:0;
y=Math.max(-vs,Math.min(vs,y));a.push([u,x]);b.push([u,y])}
const ym=Math.max(A,...b.map(p=>Math.abs(p[1])))*1.15;plot($('xcv'),{x0:0,x1:2,y0:-ym,y1:ym,xl:'t (cycles)',yl:'V',ln:[{p:a,c:'sig',w:2},{p:b,c:'out',w:3}]});
am=['v_out = −1/(R·C)·∫v_in dt. Ideal: starts at 0 and drifts (offset) until the op-amp saturates.',`One pole: H = −(R2/R1)/(1+s·R2·C). DC gain ${f(R2/R)}, corner 1/(2π·R2·C) = ${f(159.155/(R2*C),1)} Hz.`,'Diode drops 0.7 V: a 1 V signal loses most of its half-wave (green/red shows it).','Op-amp + diode in the loop compensates the drop: almost perfect half-wave. But the op-amp swings to negative saturation when blocked.',`D1 and D2: v_in > 0 → v_out = −(R2/R1)·v_in = ${f(-R2/R*A)} V peak; v_in < 0 → 0. No saturation.`][k];
$('xres').innerHTML=`<div class="res">${am}</div><div class="say">Blue = input · orange = output</div>`}
function vtc(){const d=V('xv'),vo=d-.1,il=.27*d,ih=.63*d,p=[[0,vo],[il,vo],[ih,.1],[d,.1]];plot($('vtc'),{x0:0,x1:d,y0:0,y1:d*1.05,xl:'v_I (V)',yl:'v_O (V)',ln:[{p:[[0,d],[d/2,d],[d/2,0],[d,0]],c:'line',d:[5,4],w:2},{p,c:'out',w:3},{p:[[il,0],[il,vo]],c:'sig',d:[3,3],w:1.5},{p:[[ih,0],[ih,vo]],c:'ok',d:[3,3],w:1.5}]});
$('vres').innerHTML=`<div class="res">Dashed = ideal (sharp switch at V<sub>DD</sub>/2). Orange = real.<br>V<sub>IL</sub> = ${f(il)} V (blue) · V<sub>IH</sub> = ${f(ih)} V (green) · V<sub>OH</sub> = ${f(vo)} V · V<sub>OL</sub> = 0.1 V<br>NM<sub>H</sub> = ${f(vo-ih)} V · NM<sub>L</sub> = ${f(il-.1)} V. Between V<sub>IL</sub> and V<sub>IH</sub>: don’t be there (both transistors conduct).</div>`}
function xdb(){const g=V('xd');$('xdb').innerHTML=`${g} dB = 10<sup>${g}/20</sup> = ${Math.round(10**(g/20)).toLocaleString('en')} V/V`}
const _d5=draw;draw=function(){_d5();xop();vtc();xdb()};

