let EXD={};try{EXD=JSON.parse(localStorage.getItem('tecEXD')||'{}')}catch(e){}
const RCP={'Op-amps':['Negative feedback? Then <b>v₊ = v₋</b>.','Input currents are <b>0</b>.','Write KCL at the − node (or the divider at +).','Solve for v_out.','Check saturation: |v_out| ≤ V_sat.'],'Logic families':['List the data (V_OH, V_IL, currents, C, f…).','Pick the formula: NM, fan-out, P = C·V²·f, delay.','Keep units: pF·V²·MHz = µW.','Do <b>both</b> states and keep the worst.','Does the number make sense?']},DRC=['Redraw the circuit and mark the unknown.','Write what you know and what you need.','Pick the law: Ohm, KCL, KVL, Thevenin…','Solve step by step, with units.','Check the result makes sense.'];
let EXS={},EXC={};
const stp=t=>{const a=t.split(/(?<=[.:])\s+(?=[A-Z(<])|\s(?=\(\d\)\s)/),o=[];a.forEach(x=>{if(o.length&&(x.replace(/<[^>]+>/g,'').length<14||/:\s*$/.test(o[o.length-1].replace(/<[^>]+>/g,''))))o[o.length-1]+=' '+x;else o.push(x)});return o};
$('exl').insertAdjacentHTML('beforebegin','<div id="exh" class="say"></div><div class="say"><b>🧭 Method:</b> 1 Underline the data · 2 Name the topic · 3 Write the formula · 4 Plug numbers with units · 5 Check it makes sense. Open <b>Coach me</b> for step-by-step help.</div>');
exr=function(){const k=$('exf').value;EXS={};$('exh').innerHTML=`✅ Solved ${Object.keys(EXD).length}/${EX.length}`;$('exl').innerHTML=EX.map((e,i)=>[e,i]).filter(([e])=>!k||e[0]==k).map(([e,i])=>{EXS[i]=stp(e[3]);EXC[i]=0;return `<div class="box ms ${EXD[i]?'ok':''}"><h3>${EXD[i]?'✅':'🎯'} ${e[1]}</h3><span class="tag" style="background:${col('blue')}">${e[0]}</span><p>${e[2]}</p><details><summary>🧭 Coach me (step by step)</summary><ol>${(RCP[e[0]]||DRC).map(x=>'<li>'+x+'</li>').join('')}</ol><div class="cst" id="cst${i}"></div><button class="b" data-cs="${i}">▶ Next hint</button></details><details><summary>💡 Show full answer</summary><p>${e[3]}</p></details><button class="b" data-dn="${i}">${EXD[i]?'↩ Not solved':'✅ I solved it'}</button></div>`}).join('')};
$('exf').onchange=exr;
$('exl').onclick=e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.cs){const i=+d.cs,s=EXS[i],c=EXC[i]++;if(c<s.length)$('cst'+i).insertAdjacentHTML('beforeend',`<div class="say"><b>Step ${c+1}/${s.length}:</b> ${s[c]}</div>`);if(c+1>=s.length)b.outerHTML='<small>🎉 That was everything. Now try it yourself in Practice!</small>'}else if(d.dn){if(EXD[d.dn])delete EXD[d.dn];else EXD[d.dn]=1;try{localStorage.setItem('tecEXD',JSON.stringify(EXD))}catch(x){}exr()}};
